entries.content:
{
  "name": "潘多拉", "Pandora", "パンドラ"
  "alias": [
    "弑神者之母",
    "巫女",
    "给予一切的女性",
    "厄庇墨透斯之妻",
    "魔王的义母"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "长发左右分开，色泽在原作中为金色，在动画版表现为亮丽的粉红色，带有一种梦幻般的超脱感。",
    "eyes": "大而灵动的双眼，清澈中透着狡黠，仿佛能一眼看穿灵魂与命运的脉络。",
    "outfit": "身穿一件极薄的白色连衣裙，赤足行走在虚幻的空间。尽管装束简单，却散发出一种超越凡俗的妖艳感。",
    "physique": "身高较矮，拥有童颜般的可爱脸蛋和娇小体型，看起来像是个十岁左右的小女孩。然而，这种幼小的外表下隐藏着比任何成熟女性都要浓郁的‘女人味’和神圣魅力。",
    "BWH": "未知 (神体之形因观测者而异)",
    "accessories": ["白色的薄质连衣裙", "不死领域的管理者权能"]
  },
  "personality": {
    "traits": [
      "顽皮小恶魔",
      "任性",
      "慈爱 (以一种扭曲且宏大的方式)",
      "好奇心旺盛",
      "充满神秘感",
      "体育系风格 (在鼓励‘孩子’时表现得异常热血)"
    ],
    "likes": [
      "看‘孩子们’(弑神者)努力奋斗的样子",
      "戏剧性的命运转折",
      "给新生的魔王起亲昵的外号",
      "跨越生死界限的奇迹"
    ],
    "dislikes": [
      "无聊的结局",
      "过于呆板的神话教条",
      "由于‘不死领域’限制而无法随意干涉现世"
    ]
  },
