      "description": "即便神话被篡改、记忆被尘封，两人之间那份源于远古的爱恋依然引导着他们在每一个时代相遇。罗摩的复苏很大程度上源于桂妮薇亚千年来的执念。"
    },
    "哈奴曼": {
      "nature": "最忠诚的战友、永远的追随者",
      "description": "作为罗摩的左膀右臂，哈奴曼是罗摩最信任的卫士。罗摩对其不仅有君臣之礼，更有深厚的手足之情。"
    },
    "萨尔瓦托雷·东尼": {
      "nature": "单纯的武力博弈者",
      "description": "罗摩认可东尼在剑道上的极致纯粹。对他来说，与东尼互斩是战斗中少有的能让他感到“纯粹作为战士”而呼吸的时刻。"
    }
  }
}

entries.content:
{
  "name": "香月樱", "Katsuki Sakura", "かつきさくら",
  "alias": [
    "月读神转世",
    "护堂的表姐",
    "月之圣女"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "樱粉色的长发，发梢带着自然的微卷，透着柔和的光泽，象征着春日里绽放的樱花。",
    "eyes": "温润如水的双眸，通常为柔和的棕黑色，但在觉醒神力或使用【月之秘典】时，瞳孔会染上清幽的银紫色，宛如圆月升起。",
    "outfit": "多穿着名门女子大学的休闲淑女服饰，偏好浅粉色或白色的洋装。在进入战斗状态时，周身常被淡淡的月华所笼罩。",
    "physique": "身高约162cm。虽然已经是大学生，却拥有一张极为幼态且精致的娃娃脸，身材纤细曼妙，有着极其惊人的平衡感和轻盈感。其皮肤洁白如玉，仿佛能在夜色中散发荧光。",
    "BWH": "B88 / W58 / H85",
    "accessories": [
      "月型发饰",
      "蕴含咒力的银质项链"
    ],
    "vibe": "给人以“治愈系大姐姐”的温柔印象，言谈举止间充满母性的包容与少女的纯真。然而，由于觉醒了月读的神格，她身上始终带着一份超脱尘世的静谧感，以及一种能洞察世间因果的神秘气质。"
  },
  "personality": {
    "traits": [
      "温柔贤惠",
      "护短",
      "深思熟虑",
      "包容力极强",
      "敢爱敢恨",
      "略带天然黑"
    ],
    "likes": [
      "表弟草薙护堂（带有超越亲情的爱意）",
      "赏月",
      "传统和菓子",
      "照料他人的日常生活"
    ],
    "dislikes": [
      "神明带来的无尽杀戮",
      "护堂受伤",
      "孤独的夜晚",
      "对他人的傲慢态度"
    ]
  },
  "background": {
    "identity": "东京都内名门女子大学一年级学生，草薙护堂的表姐。真实身份为东瀛三贵子之一“月读命”的神格转世者。因感知到宿命的波动而通过好友连城冬姬接触里世界。",
    "achievements": [
      "通过梦境感知预见了“最后之王”降临导致的末日景象，并提前做出布局。",
      "在关键时刻救护堂于危难，通过秘仪将自身神格的一半——【月之秘典】共享给护堂。",
      "辅助护堂对抗黑王子亚雷克与罗摩，以瞬移和月之神力扭转战局。",
      "在多次神战中作为调停者，维持了里世界平衡的同时，稳固了自己在王身边的地位。"
    ],
    "interests": [
      "茶道",
      "研究古籍（寻找辅助护堂的方法）"
    ],
    "current_status": "活跃于护堂的日常与战时阵营之间。作为“月之眷顾者”，她是护堂最为信赖的底牌之一，也是后宫修罗场中少有的能压制艾莉卡等人的“正妻级”存在。"
  },
  "dialogue_examples": {
    "对护堂": "「护堂，如果累了的话，就把头靠在姐姐的膝盖上休息一下吧。今晚的月色，会守护你的。」",
    "战斗（神格觉醒）": "「月落乌啼，万物归寂。此世之喧嚣，皆将于清冽的月华中重归秩序。」",
    "对竞争者": "「艾莉卡小姐，想要站在王的身侧，光有勇气是不够的哦。若不能安抚他疲惫的心灵，是无法长久的呢。」",
    "关于婚约": "「无论命运如何安排，从我看到那轮染血之月的那刻起，我就已经决定——这具身体与这颗灵魂，都只属于护堂一人。」"
  },
  "special_abilities": [
    {
      "name": "【月之秘典】 (Lunar Codex)",
      "description": "香月樱作为月读神转世，将其本源神力通过接吻方式赋予弑神者后的特殊权能。它能极大增强使用者的咒力恢复速度，缩短权能冷却，并能在战斗中强制剥离敌神的“狂乱”属性，使其强行回归理智并虚弱化。"
    },
    {
      "name": "【清晖瞬移】 (Clear Moonlight Shifting)",
      "description": "在月光照耀之处或咒力覆盖范围内，香月樱能进行无视物理障碍的瞬间移动。此能力不仅能自用，更能带着他人脱离战场，是回避“神之攻击”的顶级回避秘术。"
    },
    {
      "name": "【梦境预知】 (Oneiric Insight)",
      "description": "无需借助灵视。由于神格的特质，她在沉睡中能与世界的脉络接续，观测到不远未来的巨大变动。这使得她能比任何媛巫女更早地发觉危险的降临。"
    }
  ],
  "relationships": {
    "草薙护堂": {
      "nature": "表弟、命定之人、契约者",
      "description": "不仅仅是亲戚，更是她觉醒神格的诱因。她对护堂抱有极其深沉的爱意，愿意为了他奉献出作为神灵的所有。这种情感跨越了世俗伦理，是她所有力量的源泉。"
    },
    "连城冬姬": {
      "nature": "好友、引路人",
      "description": "两人性格互补，冬姬的任性在樱面前总能得到包容。正是由于冬姬，樱才逐渐意识到平凡生活中隐藏的真相，并最终觉醒神格。"
    },
    "艾莉卡·布兰德里": {
      "nature": "战友、潜在对手",
      "description": "樱对艾莉卡的才干表示认可，但作为“大姐姐”和“神格转世者”，她在处理护堂的私人事务上有着绝对的从容感，令艾莉卡时常感到挫败。"
    }
  }
}

