{
  "name": "六波罗莲", "Rokuhara Ren", "ろくはら れん",
  "alias": [
    "第八位王",
    "弑神者 (Campione)",
    "魔王",
    "王子的笨蛋"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "稍微有些褪色的茶色短发，显得有些花哨且不羁，带有典型的下町青年风格。",
    "eyes": "深棕色的眼眸，平视他人时流露出随性且易于亲近的特质，但在发动“因果报应”时会变得极其锐利。左眼在发动【时间凝固】时会呈现彩虹色的光泽。",
    "outfit": "多穿着休闲的现代服饰，如夹克搭配条纹T恤和休闲裤。整体给人以活力充沛、不修边幅的大学生印象。",
    "physique": "身高178cm，体重60kg。体型纤细且修长，但由于长期的武术模仿癖好与体育特长生经历，肌肉分布极其匀称且具有爆发力。拥有远超常人的敏捷性与动态视力。",
    "accessories": [
      "友爱之带 (作为权能核心隐藏于体内)",
      "由于其弑神者的体质，任何服饰在激烈的权能冲突中都难以保持完好。"
    ],
    "vibe": "外表看起来是个轻浮且容易说话的“王子气”帅哥，不擅长也不喜欢使用敬语。他有着天生的社交牛逼症，能迅速与陌生人建立“朋友”关系。但在那层随性的外表下，隐藏着弑神者特有的果决与对胜利的执着，是那种在关键时刻会毫不犹豫舍弃伦理追求最优解的类型。"
  },
  "personality": {
    "traits": [
      "极度自由自在",
      "天生的社交者",
      "和平主义者（尽量避免暴力）",
      "实用主义者（为了胜负可以抛弃伦理）",
      "武学天才（擅长模仿他人动作）",
      "女性缘极佳",
      "缺乏弑神者的傲慢（因与神共生）"
    ],
    "likes": [
      "和平的日常",
      "交朋友（特别是能互相帮助的朋友）",
      "各种运动（滑板、舞蹈、格斗技、足球）",
      "自由且不被束缚的生活"
    ],
    "dislikes": [
      "毫无意义的杀戮",
      "复杂的魔术知识与神话术语",
      "被麻烦的规矩束缚",
      "心口不一的人"
    ]
  },
  "background": {
    "identity": "原本是东京葛饰区龟有的普通青年，由于在西班牙的毕业旅行中卷入神话动乱，意外弑杀复仇女神涅墨西斯并吞噬美神阿佛洛狄忒，成为了继草薙护堂之后的第八位弑神者。现受聘于魔术结社『Campiones』，穿梭于各个神域阻止世界崩溃。",
    "achievements": [
      "在西班牙弑杀涅墨西斯，获得核心权能【因果报应】。",
      "通过神具《友爱之带》融合阿佛洛狄忒，开创了与神灵共生的先例。",
      "成功击败胜利女神尼姬，并获得强化眷属的【翼之契约】。",
      "在希腊神域等多个平行位面（神域）中完成了神话重组与秩序修正任务。"
    ],
    "interests": [
      "钻研各种不需要咒力的运动技巧",
      "由于社交达人属性，致力于在世界各地寻找“值得信赖的朋友”"
    ],
    "current_status": "活跃于连接不同平行世界的“神域”前线。虽然在里世界被称为“王”，但他本人更认同自己作为“工作员”或“代理人”的身份。"
  },
  "dialogue_examples": {
    "对神明": "「如果是复仇的话，就请找神话里的那个我吧。现在的我只是个想赶紧回日本吃顿好的普通人而已。」",
    "日常": "「敬语什么的太麻烦了吧？我们不是朋友吗？朋友之间直接叫名字就好啦！」",
    "战斗（咏唱）": "「未来之事起于过去之因。命运啊，展现因果之关联吧！愿正义之制裁降于汝身！」",
    "关于同伴": "「史黛拉、梨于奈，既然已经结下了契约，那我们就只有获胜这一条路可走了对吧？」"
  },
  "special_abilities": [
    {
      "name": "【因果报应】 (Divine Retribution)",
      "description": "来源神明：涅墨西斯 (希腊神话)。能看破极高速的攻击，并随心所欲地控制伤害的返还点。既能瞬间反弹，也能将灾厄储存起来择机释放。此权能还赋予了莲神速回避与审判恶行的神罚之力。"
    },
    {
      "name": "【朋友之环】 (Friendship Circle)",
      "description": "来源神明：阿佛洛狄忒 (希腊神话)。由于美神存在于莲的体内，他能以“拜托”的形式通过美神召唤与之相关的希腊众神并借用力量。这种权能极度依赖莲的人格魅力与社交能力，是不确定的奇迹。"
    },
    {
      "name": "【翼之契约】 (Wing Covenant)",
      "description": "来源神明：尼姬 (希腊神话)。弑神者与眷属建立深度连接的权能。能赋予眷属足以对抗神灵的咒力，并在心灵上建立感应。眷属若击败敌神，其战果亦归于莲。"
    },
    {
      "name": "【时间凝固】 (Stagnant Eternity)",
      "description": "来源神明：雅典娜 (希腊神话)。通过左眼的魔眼释放，能瞬间冻结视野内的一切事物（包括时间本身、权能效果甚至无形的概念）。在全力发动时，足以定格同等级的弑神者数秒乃至更久。"
    }
  ],
  "relationships": {
    "鸟羽梨于奈": {
      "nature": "未婚妻、最重要的眷属、契约之剑",
      "description": "日本最高阶的阴阳师。由于罗濠教主的影响与家族婚约，成为了莲最坚实的后盾。通过【翼之契约】，她成为了能够正面干扰弑神者战斗的强大存在。"
    },
    "史黛拉 (阿佛洛狄忒)": {
