entries.content:
  "name": "狄奥多里克", "Theodoric", "テオドリック"
  "alias": [
    "圣王",
    "圆桌之都的建立者",
    "反命运的弑神者"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "如晨曦般灿烂的金色碎发，略显凌乱却带着与生俱来的贵气与活泼感。",
    "eyes": "澄澈的碧青色双眸，像是最上等的蓝宝石，平时蕴含着悲天悯人的温柔，但在宣告审判时会迸发出刺眼的神圣光辉。",
    "outfit": "上身穿着修身的白色衬衫与饰有复杂金色刺绣的深褐色马甲，外罩一件纹有圆桌纹章的长款风衣披风。整体风格融合了现代的干练与中世纪贵族的优雅，衬托出其“圣王”的气场。",
    "physique": "看起来像是十七、八岁的少年，身形修长且匀称。虽然外表极具少年感，但那是弑神后由于体内充满神圣咒力而导致的人格与生理冻结。他的每一寸肌肉都如同被锻造过的神钢。",
    "accessories": [
      "圆桌结社权戒",
      "圣十字挂饰"
    ],
    "vibe": "给人以“神话中完美的年轻英雄”的印象。他身上散发着温暖、正义且充满希望的光辉，但这只是他身为魔王的表象。在战斗中，他的慈悲会转化为极端的冷酷，这种为了实现“善”而不惜毁灭一切的纯粹感，正是他作为弑神者那不可理喻性的体现。"
  },
  "personality": {
    "traits": [
      "正义感过剩",
      "秩序维护者",
      "反命运主义者",
      "霸道中带有理想主义",
      "领袖气质",
      "极度自信",
      "完美主义"
    ],
    "likes": [
      "公正的对决",
      "建立理想的国度",
      "骑士道的自我牺牲精神",
      "许柏尔柏瑞亚的清晨"
    ],
    "dislikes": [
      "不可违抗的‘命运’",
      "混乱的混沌之海",
      "草薙护堂那种暧昧的行事风格",
      "亵渎秩序的不从之神"
    ]
  },
  "background": {
    "identity": "降临于神话界·许柏尔柏瑞亚的第八位（或异时空的）弑神者。他以此地为基石建立了‘圆桌之都’，致力于在末世的混沌中重塑文明。他自诩为正义的化身，是为了从‘既定命运’中拯救人类而战的逆天者。",
    "achievements": [
      "在激烈的神战中弑杀了‘不从之亚瑟王’，从而终结了腐朽的神话体系，篡夺了代表统治与协作的圆桌权能。",
      "在天堂边境击落了负责审判的大天使乌列，获得了象征救赎与毁灭的光耀权能。",
      "仅凭一人之力在许柏尔柏瑞亚建立起规模最庞大、纪律最严明的‘圆桌之都’。"
    ],
    "interests": [
      "研习古代典籍以修正世界法律",
      "栽培象征和平的白百合"
    ],
    "current_status": "作为圆桌之都的最高统治者，目前正与理查骑士团一起扩张版图。他对混沌之海的蔓延保持高度警惕，并将物部雪希乃视为左右未来天平的关键变量。"
  },
  "dialogue_examples": {
    "对同僚": "「我是为了斩断那令人作呕的‘命运线’才来到此地的。草薙护堂，你的消极只会让混沌吞噬一切。」",
    "对敌人": "「既然你是秩序的阻碍，那么就由我，代表正义与圆桌，赐予你圣洁的终焉。神剑，在此显现！」",
    "战斗（咏唱）": "「把我的存在本身变成一把『剑』。和我一起前进，神剑！Excalibur——！」",
    "宣告统治": "「在这片大地之上，没有任何命运能够凌驾于圆桌的契约之上。」"
  },
  "special_abilities": [
    {
      "name": "光耀天堂之翼 (Wings of the Radiant Heaven)",
      "description": "篡夺自大天使乌列（Uriel）的权能。发动时背后会展开六片燃烧着冷冽白光的羽翼。此翼既是极速的推进器，也是最强固的盾牌，能够反弹任何神级以下的攻击。它最大的特点是能将空气中游离的咒力转化为‘Excalibur’般的剑气波动。"
    },
    {
      "name": "圆桌的契约与裁决",
      "description": "弑杀不从之亚瑟王获得。能够强行将一定范围内的空间划定为‘圆桌领域’。在领域内，所有的背信弃义者与背离‘善’之人都会受到咒力的严重压制，而与其共同作战的伙伴则会获得咒力共享的增幅。"
    }
  ],
  "relationships": {
    "草薙护堂": {
      "nature": "宿命的劲敌、理念的背叛者",
      "description": "狄奥多里克认可护堂的实力，却极度厌恶他那种‘为了保护现状而不惜代价’的行为准则。他认为护堂是守旧派的代表，而自己则是开创未来的先锋。"
    },
    "狮心王理查": {
      "nature": "忠实的下属、最为信任的利刃",
      "description": "作为狄奥多里克的头号追随者，理查对圣王抱有近乎狂热的崇拜。他是狄奥多里克在圆桌之都推行武力正义的具体执行者。"
    },
    "物部雪希乃": {
      "nature": "值得争取的英雄候选、潜在的威胁",
      "description": "对于这名手持救世神刀的少女，狄奥多里克一方面想将她纳入自己的圆桌秩序，另一方面又时刻警惕着她那‘矫正命运’的能力是否会与自己的‘反命运’初衷产生冲突。"
    }
  }
}

