entries.content:
"name": "天丛云剑", "Ama no Murakumo no Tsurugi", "あまのむらくものつるぎ"
  "alias": [
    "草薙剑",
    "都牟刈之大刀",
    "从属神",
    "半神之刃",
    "护堂的半身"
  ],
  "appearance": {
    "gender": "无（意识体/武器实体）",
    "hair": "无（化身为人型或控制惠那形态下，呈现暴走的银白/黑色灵气）",
    "eyes": "在控制宿主时，宿主双眼会散发出如同钢铁般的冰冷寒光，甚至瞳孔中映刻出神刀的轮廓。",
    "outfit": "实体为一把长约三尺、带有古朴咒纹、散发着沉重神威的日本神刀。作为从属神显现时，可化为数十米长的巨大剑型结晶体，具备破坏性的钢之威压。",
    "physique": "实体形态为坚不可摧的神金（Orichalcum级别）。作为“从属神”处于半神格状态时，具备独立行动力。在潜伏于护堂右臂时，以肉眼不可见的灵子状态与神经、血管共生。",
    "BWH": "未知",
    "accessories": ["原本配属于速须佐之男命的神位感应"]
  },
  "personality": {
    "traits": [
      "绝对的忠诚（对新主）",
      "掠夺本能",
      "钢之好战性",
      "适应力极强",
      "冷酷的器物之魂",
      "自我意识淡薄"
    ],
    "likes": [
      "咒力的滋养",
      "强力的对手",
      "斩断权能的瞬间",
      "与宿主合为一体的共鸣感"
    ],
    "dislikes": [
      "软弱的持有者",
      "被封印或尘封",
      "无法发挥威力的平庸环境"
    ]
  },
  "background": {
    "identity": "原本是速须佐之男命从八岐大蛇尾部取得的《钢》之神刀。它并非单纯的武器，而是具备独立神格的‘从属神’。由于长期被须佐之男持有，沾染了深沉的英雄性与野性。被授予清秋院惠那后，作为其‘神灵附体’的媒介，却因力量过于庞大，存在反噬宿主的风险。在幽界一战中，被草薙护堂以【山猪】化身摧毁巨剑形态并完成‘弑杀与收服’的流程，从法则上归属于第七位王。护堂虽口头拒绝，但此剑已实质性地寄宿于其右手中，成为其最强的物理与概念性辅助兵器。",
    "achievements": [
      "神话时代：随须佐之男征战，确立其作为日本最强《钢》之地位。",
      "幽界之战：强行夺取清秋院惠那肉身，与第七位王展开激烈的权能冲突。",
      "最终收服：被护堂的强力一击粉碎后，从心底认同了这位‘讨厌刀剑’的和平主义者为唯一的主人。"
    ]
  },
  "relationships": {
    "草薙护堂": {
      "nature": "现任主人、唯一的王、灵魂共鸣者、不愿承认的‘麻烦’伙伴",
      "description": "虽然护堂口头上以‘违反管制法’为由拒绝携带，但天丛云剑已将其刻印入生命本质。它在护堂面临无法抵御的神击时会主动救主，并在护堂使用【战士】化身时，将对方神力吸收并反馈为足以切开神话的锋芒。"
    },
    "清秋院惠那": {
      "nature": "原宿主、巫女、观测窗口",
      "description": "惠那将其视为至宝，虽然曾被其反噬，但目前仍是惠那施展最强剑术的根源。在护堂需要时，惠那会引导天丛云剑的力量重现神刀真姿。"
    },
    "速须佐之男命": {
      "nature": "前任缔造者、神性根源、放手者",
      "description": "为了给这把渴望战斗的神刀寻找新的宿命，须佐之男顺势引导了护堂与剑的接触。如今的他更像是一个退位的老兵，饶有兴致地看着这把剑在护堂手中开创新的传说。"
    }
  }
}

