  ],
  "appearance": {
    "gender": "男性",
    "hair": "整个面部被密密麻麻、如同钢针般坚硬的黑色短毛覆盖，头顶耸立着短秃的三角形猪耳。",
    "eyes": "圆溜溜且泛着幽冷凶光的猪眼，瞳孔中映衬着北极星的倒影。",
    "outfit": "身披厚重而冰冷的漆黑铠甲，铠甲上隐约刻有北斗七星的纹路。这身黑衣黑铠不仅是防御，更是星辰重量的载体。",
    "physique": "身高约2.5米（常态），体型异常魁梧、甚至显得臃肿肥大，如同一个充满福态的巨汉。然而在厚重的脂肪层下，是足以撞碎山岳的非比寻常的肌肉。鼻子长而湿润，嘴角两侧支起尖锐的白色獠牙，整个人散发出令人窒息的蛮力与狂暴神威。",
    "BWH": "未知",
    "accessories": ["九齿钉耙（未显现前为黑铠配件）", "星辰符箓"]
  },
  "personality": {
    "traits": [
      "蛮横狂暴",
      "贪婪",
      "豪迈",
      "极端好战",
      "忠于原始本能",
      "对权位的眷恋",
      "威压感"
    ],
    "likes": [
      "祭祀的血肉",
      "高烈度的战斗",
      "星光的照耀",
      "摧毁文明的秩序",
      "月光下的宁静（潜在人性）"
    ],
    "dislikes": [
      "三藏法师的紧箍呪（潜在厌恶）",
      "‘悟’字带来的束缚",
      "比自己更强的力量压制",
      "被称为‘呆子’（会引发暴走）"
    ]
  },
  "background": {
    "identity": "在成为随行西天的祭师之前，它是支配福陵山、以吃人为生的凶神——猪刚鬣。其真身乃是道教北极四圣之首的“天蓬元帅”。由于不满神话中被赋予的‘滑稽’与‘被奴役’的结局，他脱离了神话的编排，作为‘不从之神’降临于世。他不仅拥有野猪的蛮力与多变的妖力，更兼具星宿之神指挥神兵、操控雷法、变幻法相的威能。他是贪欲与武力的结合体，是降临在大地上的黑色星灾。",
  },
  "relationships": {
    "不从之齐天大圣": {
      "nature": "曾经的师兄弟、宿敌、竞争者",
    },
    "弑神者": {
      "nature": "觊觎其权能的狩猎者、渴望一战的强敌",
    },
    "正史编纂委员会": {
      "nature": "如蝼蚁般试图封印他的祭祀组织"
    }
  }
}

