entries.content:
"name": "米诺斯", "Minos", "ミノス"
  "alias": [
    "米诺陶诺斯",
    "克里特之王",
    "迷宫的支配者",
    "大地之王",
    "《钢》之军神"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "粗犷的深色须发，如同狮子的鬃毛般狂野，彰显着古老半兽神祗的原始生命力。",
    "eyes": "如岩浆般灼热且充满压迫感的瞳孔，透着不容置疑的王道威严，凡人直视即会丧失斗志甚至陷入疯狂。",
    "outfit": "上身赤裸，展示出如花岗岩般隆起的肌肉；腰间围着充满古希腊风情的粗犷腰蓑，披着一件深红色的巨大斗篷。这件斗篷在风中猎猎作响，宛如流动的新鲜血液。",
    "physique": "常态下身高约30米。身处于海洋或水域环境中时，其体积会膨胀至50米。而在进入自身构建的“迷宫”领域时，为了适应战斗，形体会浓缩至5米。这种体型变化本身就蕴含着极高的神力波动。",
    "BWH": "未知 (神体规模非凡人可测)",
    "accessories": ["红色斗篷", "大地之震慑"]
  },
  "personality": {
    "traits": [
      "极度威严",
      "霸道无双",
      "勇猛果敢",
      "崇尚强者",
      "充满支配欲",
      "不屑于诡计"
    ],
    "likes": [
      "与强者的厮杀",
      "大地的厚重感",
      "克里特岛的繁荣（神话记忆）",
      "充满敬畏的祭祀"
    ],
    "dislikes": [
      "弱者的吠叫",
      "软弱的术式诡计",
      "被神话条文束缚"
    ]
  },
  "background": {
    "identity": "身为不从之神降临的米诺斯，是克里特文明的神王。他不仅与海神波塞冬有着极深的渊源，更是司掌丰收的大地之神。他在神话中与“牛”的意象密不可分，其本质是作为“米诺陶诺斯”这一恐怖怪物原型的最高神格。作为《钢》之英雄神，他拥有着极其强悍的突进力与身体机能，即便面对闪电这类天罚级的权能也能依靠强韧的神性正面硬撼。",
    "achievements": [
      "统治古代克里特文明，确立地中海的霸权。",
      "化身迷宫之主，狩猎无数英雄。",
      "以大地王者的身份向弑神者（魔王）宣战，视死如归的最高位战神。"
    ]
  },
  "special_abilities": [
    {
      "name": "【迷宫的大地之王】",
      "description": "通过操纵大地，米诺斯能够瞬间将周围的环境改造成如同神话中“拉比林斯（Labyrinth）”一样的错综迷宫。在这个领域内，他的体型会浓缩，力量与机动力反而会因密度的增加而大幅度强化。"
    },
    {
      "name": "【牛神的突进】",
      "description": "其强悍的腿部肌肉能提供一瞬间加速到时速三百公里的恐怖爆发力，伴随着大地的震动，足以撞穿任何神圣护盾或山脉。"
    },
    {
      "name": "【强制解除：OOOOOOLAAAAAANNNNNN！！】",
      "description": "具有消除魔术术式、强制解除弑神者权能的神圣咏唱。这是作为上位神灵对现实法则的强力干涉，是对“虚伪奇迹”的终极否决。"
    }
  ],
  "relationships": {
    "波塞冬": {
      "nature": "渊源深厚的神话亲缘",
      "description": "给予米诺斯白牛的海洋主宰，两者在克里特文明的信仰中交错。"
    },
    "弑神者": {
      "nature": "宿命的死敌",
      "description": "视其为禁忌的魔王，但同时也期待被强大的弑神者吞噬其血肉，完成宿命的更替。"
    }
  }
}

