entries.content:
"name": "萨图尔努斯", "Saturnus", "サトゥルヌス"
  "alias": [
    "农耕之神",
    "圣诞节之祖",
    "黄金时代的统治者",
    "被囚禁的古老神王",
    "时光的收割者"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "如枯萎的麦穗般的枯黄色长发，凌乱地披散在肩头，透着一股被囚禁已久的颓废与沧桑。",
    "eyes": "暗金色的瞳孔，闪烁着不稳定的光芒，仿佛时刻在清醒与狂乱之间转换，眼眸深处沉淀着神话时代的厚重历史。",
    "outfit": "身上缠绕着锈迹斑斑的沉重铁链，这些铁链是朱彼特施加的封印化身。他披着一件破旧的暗红色长袍，腰间束着草绳，脚踩草鞋，形象兼具了王者之尊与农夫之卑。",
    "physique": "身形高大却显得消瘦，皮肤如同干枯的大地。尽管看起来虚弱，但举手投足间释放出的咒力能让周围的植物疯狂生长后迅速腐朽。",
    "BWH": "未知",
    "accessories": ["巨大的神圣镰刀（Harpe）", "禁锢双手的雷霆锁链（咒物）"],
  },
  "personality": {
    "traits": [
      "矛盾性",
      "狂乱",
      "宽容与残忍并存",
      "对秩序的厌恶",
      "极端的自由主义"
    ],
    "likes": [
      "萨图尔努斯大祭的混乱",
      "丰收的景象",
      "地位反转带来的讽刺感",
      "醇厚的美酒",
      "春天的第一缕微风"
    ],
    "dislikes": [
      "主神朱彼特的规则",
      "永远的囚禁",
      "所谓的‘文明秩序’",
      "雷霆的气息"
    ]
  },
  "background": {
    "identity": "古罗马神话中的农耕之神。在远古的黄金时代，他曾是统治万物的至高神王。然而，他最终被亲子朱彼特推翻并幽禁。作为‘不从之神’降临的萨图尔努斯，是由于现代人类庆祝圣诞节（其源头为萨图尔努斯大祭）时过度消费与享乐的行为，唤醒了他灵魂中关于‘狂乱之宴’的本质。他带着对朱彼特秩序的憎恨降临现世，试图将整个文明社会变回那个‘尊卑不分、极尽狂欢’的萨图尔努斯祭典期间，哪怕这种反转会导致文明的彻底崩塌。",
  },
  "relationships": {
    "朱彼特": {
      "nature": "逆子、宿敌、将其幽禁的施法者",
    },
    "潘多拉": {
      "nature": "将其力量进行再编译的‘母亲’（若被弑杀）",
    },
    "弑神者": {
      "nature": "猎物或是即将终结其囚禁生涯的‘救赎者’",
    }
  }
}

