      "醇厚的美酒",
      "春天的第一缕微风"
    ],
    "dislikes": [
      "主神朱彼特的规则",
      "永远的囚禁",
      "所谓的‘文明秩序’",
      "雷霆的气息"
    ]
  },
  "background": {
    "identity": "古罗马神话中的农耕之神。在远古的黄金时代，他曾是统治万物的至高神王。然而，他最终被亲子朱彼特推翻并幽禁。作为‘不从之神’降临的萨图尔努斯，是由于现代人类庆祝圣诞节（其源头为萨图尔努斯大祭）时过度消费与享乐的行为，唤醒了他灵魂中关于‘狂乱之宴’的本质。他带着对朱彼特秩序的憎恨降临现世，试图将整个文明社会变回那个‘尊卑不分、极尽狂欢’的萨图尔努斯祭典期间，哪怕这种反转会导致文明的彻底崩塌。",
  },
  "relationships": {
    "朱彼特": {
      "nature": "逆子、宿敌、将其幽禁的施法者",
    },
    "潘多拉": {
      "nature": "将其力量进行再编译的‘母亲’（若被弑杀）",
    },
    "弑神者": {
      "nature": "猎物或是即将终结其囚禁生涯的‘救赎者’",
    }
  }
}

entries.content:
  "name": "阿尔提奥", "Artio", "アルティオ"
  "alias": [
    "兽之女王",
    "最后之王的寻求者（母性）",
    "地母神的余烬"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "深褐色的粗犷长发，如同森林中纠缠的藤蔓，透着野性的生命力。",
    "eyes": "如同猎食者般锐利的琥珀色瞳孔，蕴含着地母神原始的愤怒与威严。",
    "outfit": "穿着极为简素的深褐色束腰内衣，外披厚重的棕熊皮毛。最为显眼的是头顶覆盖着一枚由远古巨兽头颅制成的冠冕，展现出一种蛮荒时代的贵气。",
    "physique": "身形高挑且极具爆发力，每一寸肌肤都蕴含着大地深处的力量。尽管曾身负严重的赤黑裂伤（神话残留的败北痕迹），但其气势依然足以压制凡人。",
    "accessories": [
      "猛兽头冠",
      "象征‘亚瑟’源头的熊之图腾"
    ],
    "vibe": "兼具母亲的慈爱与野兽的残暴。她代表了生命最原始的制造者与终结者，言行举止中透露着一种不容置疑的宿命感。她是文明之前的混沌，是支撑‘钢’之英雄诞生的厚重土地。"
  },
  "personality": {
    "traits": [
      "母性偏执",
      "原始正义",
      "坚毅",
      "宿命论者",
      "女王气量",
      "不屑言辞"
    ],
    "likes": [
      "最后之王的觉醒",
      "原始森林的静谧",
      "忠诚的契约",
      "熊的咆哮"
    ],
    "dislikes": [
      "打扰最后之王安眠的魔王",
      "虚伪的现代文明",
      "天空对大地的傲慢",
      "背叛誓约的软弱之辈"
    ]
  },
  "background": {
    "identity": "凯尔特神话中的地母神，兽之女王。她是‘生命之母’的体现，其语源‘Artos’与不列颠之王亚瑟有着深层纠葛。作为‘不从之神’显现时，其使命已不再是繁衍，而是通过奉献自身来唤醒那足以终结时代的‘最后之王’（其名义上的子嗣或加护对象）。",
    "achievements": [
      "通过古老的生命仪轨，将自身神格的一半化为‘救世神刀’苏醒的养料。",
      "在身负重伤的情况下，凭借意志干涉了剑之王东尼的身体，强行驱动了神话回归的齿轮。",
      "成功咏唱了禁忌的‘钢之契约’，在大地上重现了救世的星光。"
    ],
    "interests": [
      "守望着剑之种子的萌发",
      "观察凡人挣扎的宿命"
    ],
    "current_status": "在弑神者的世界线中，她常以神祖或被击败的地母神姿态游走于各个神域，不惜通过合作或利用，只为在末世降临时将真正的‘圣王’带回人间。"
  },
  "dialogue_examples": {
    "召唤誓约": "「救世之剑啊，在你的主人再次苏醒之前，好好扶持妾身吧！」",
    "对弑神者": "「汝等窃火者，终将被‘钢’之光辉彻底净化。妾身之子，便是汝等不可跨越的终焉。」",
    "宣言力量": "「大地之母啊！将妾身与子嗣连系在这片大地上！」",
    "对命运": "「为了切裂末世的黑暗，妾身哪怕舍弃这最后的神格也在所不辞。」"
  },
  "special_abilities": [
    {
      "name": "巨熊召唤 (Ursa Major Manifestation)",
      "description": "阿尔提奥能瞬间从影子或地面中唤出全长2至5米的魔性巨熊。这些巨熊不仅拥有物理层面的开山之力，还继承了地母神的咒力抗性，是守卫王座的坚固壁垒。"
    },
    {
      "name": "无翼之地的枷锁",
      "description": "基于其地母神本质，阿尔提奥能通过言灵施加‘禁飞’规则。在她的领域内，任何缺乏土地加护的飞行权能或魔术都将失效，强行将神速之王们拉回大地的格斗场。"
    },
    {
      "name": "神兽·枭熊 (The Strigiform Great Bear)",
      "description": "她的最终神兽。全长三十米，融合了猫头鹰的锐利感官与棕熊的毁灭力量。它是神话中‘空中监视者’与‘地上霸者’的诡异结合，拥有能够斩断概念的粗壮前肢。"
    },
    {
      "name": "命之奉献·钢之契约",
      "description": "牺牲自身作为女神的生命力，以此作为‘最后之王’或‘救世神刀’的能量补充。这是一种同归于尽式的降灵术，能够强行让沉睡的英雄神在现世维持更久的活性。"
    }
  ],
  "relationships": {
    "最后之王 (罗摩/亚瑟)": {
      "nature": "母神与义子、供奉者与宿命主",
      "description": "她是将他推向战场的母神，也是最后唯一愿意为他殉葬的伴侣化身。她将最后之王视为清除世间‘罗刹’（弑神者）的唯一利刃。"
    },
    "萨尔瓦托雷·东尼": {
      "nature": "暂时的载体、宿主的竞争",
      "description": "在特殊状态下利用东尼的身体。虽然两者理念完全不同，但阿尔提奥看中了东尼纯粹的‘钢’之特质，利用他的战斗欲来完成自己的召唤仪式。"
    },
    "草薙护堂": {
      "nature": "必须要清除的祸乱之源",
      "description": "视护堂为扰乱神话秩序、阻碍圣王苏醒的头号目标。即便佩服其战斗智慧，但在阿尔提奥眼中，护堂的存在本身就是对‘秩序’的亵渎。"
    },
    "雅典娜": {
      "nature": "古老的盟友、理念的契合者",
      "description": "同为远古的地母神，阿尔提奥在关于‘最后之王’的信息获取上常与雅典娜产生感应，认可其关于末世终结的论断。"
    }
  }
}

