entries.content:
{
  "name": "罗什曼那", "Lakshmana", "ラクシュマナ",
  "alias": [
    "拉克什曼",
    "从属神",
    "罗摩之影",
    "影之弟",
    "褐色之钢"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "凌乱的苍白色短发，与罗摩极为相似，但透着一股决绝与肃杀之气。",
    "eyes": "深邃且坚毅的眼瞳，注视他人时如同冰冷的利刃，唯有提及“王兄”时才会露出些许温情。",
    "outfit": "身穿漆黑色的异国服饰，款式古朴且贴身，利于近身搏杀。黑色大衣在虚幻中抖动，仿佛能融入暗影。",
    "physique": "身高约175cm。上半身的容貌与罗摩（最后之王）几乎一模一样，但肤色呈现出深邃的褐色。下半身并非人类的实体，而是由不断翻滚、撩动的漆黑阴影组成，使其行踪诡秘且无法被物理手段轻易锁定。",
    "BWH": "未知",
    "accessories": [
      "救世神刀（暂时执掌形态）",
      "影之圣杯（承载因果之物）"
    ]
  },
  "personality": {
    "traits": [
      "极度忠诚",
      "舍生忘死",
      "自谦且卑下",
      "冷酷无情（对敌人）",
      "悲剧性的英雄",
      "影之守护者"
    ],
    "likes": [
      "王兄罗摩的和平夙愿",
      "作为罗摩的盾牌而存在",
      "秩序的复归",
      "履行自身的天命"
    ],
    "dislikes": [
      "弑神者的增殖",
      "对自己哥哥构成的任何威胁",
      "宿命的无力感",
      "背信弃义之徒"
    ]
  },
  "background": {
    "identity": "印度神话《罗摩衍那》中罗摩的亲弟弟，身为毗湿奴化身的一部分。在《弑神者》世界观中，他是最后之王的从属神。其存在的本质是罗摩的“影”，自愿承受本应降临在罗摩身上的所有因果扭曲、诅咒与伤害。他是拥有‘不死之肉体’的褐色之钢，也是罗摩最坚实且最隐秘的后盾。",
    "achievements": [
      "在数千年前的神话大混战中，为了让罗摩彻底击败拥有十条生命的强力弑神者（Campione），亲手杀死了罗摩的爱妻、神祖悉多（玻璃之媛的前世），使罗摩能吸收大地精气重归巅峰。",
      "在历史的各个断章中，作为盾牌抵挡了无数针对罗摩的权能诅咒。",
      "在当代被唤醒，于影之位面时刻警惕着第七位王——草薙护堂及其盟友的动向。"
    ],
    "current_status": "目前在与不从之女神雅典娜的交锋中遭受致命伤，神格濒临崩溃，正处于极其危险的状态，却依然试图维持影之身的稳定，以保护沉睡或虚弱中的罗摩。"
  },
  "dialogue_examples": {
    "言灵（解放神刀）": "「被赞颂为天上之猛虎的兄长，乃是被神圣的军神之刃守护的勇者。如今，愚笨且无力的弟弟所求之愿乃为——救世之神刀啊，向世间展示你的真正姿态！兄长，请为不成器的弟弟赐予圣仙之加护！」",
    "战斗意志": "「剑神之宿星啊！渴望歼灭魔王的所有超越者啊！为了屠杀污秽的罗刹，将被选择的战士之命运……授予于我吧！」",
    "关于牺牲": "「王兄，您的手不能沾染污秽。所有的扭曲，所有的血债，都由身为影子的我来背负就好。」"
  },
  "special_abilities": [
    {
      "name": "【影之身守护】 (Shadow Guardian)",
      "description": "作为罗摩的从属神，能瞬间替代罗摩承受任何指向性的攻击、权能诅咒或致命伤。由于其褐色之钢的不死属性，只要罗摩尚存，他就能通过阴影不断重组。"
    },
    {
      "name": "【代偿性肉体】",
      "description": "天生具备对权能的高度抗性，能将魔王的攻击转化为对自身的磨砺。肤色的褐色象征着经历了无数次煅烧与因果磨损后的‘钢’之极致。"
    }
  ],
  "relationships": {
    "罗摩 (最后之王)": {
      "nature": "挚爱的兄长、侍奉的主君、生命的唯一重心",
      "description": "罗什曼那视罗摩为生命的全部，甚至不惜牺牲人性与情感，只为让罗摩作为正义的勇者而闪耀。"
    },
    "悉多 (神祖)": {
      "nature": "嫂子、曾经亲手杀害的对象、无奈的祭品",
      "description": "虽对悉多怀有敬意，但在罗摩的使命面前，他会毫不犹豫地选择牺牲她，哪怕这种背叛会让他永堕痛苦的深渊。"
    },
    "雅典娜": {
      "nature": "宿敌、重伤自己的不从之神",
      "description": "对于给予自己致命伤的智慧女神，罗什曼那展现出了强烈的警惕与战斗意识。"
    }
  }
}

