entries.content:
{
  "name": "诺亚", "Noah", "ノア",
  "alias": [
    "方舟之主",
    "引来末日之人",
    "流浪的救赎者",
    "古老的航海家"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "如银色的海浪般垂落的白发，带着岁月打磨的沧桑，长及腰际且略显凌乱。",
    "eyes": "深邃的蔚蓝色，眼底仿佛蕴含着一个永不停歇的漩涡，透着一种看穿文明生灭的淡漠与忧郁。",
    "outfit": "披着由粗糙亚麻织成的古老长袍，边缘浸透了海水的盐渍，随身携带着一根由橄榄木制成的苍老手杖。",
    "physique": "看上去是一位清瘦的老者，身形略显佝偻，但每一步跨出都让大地为之震颤。其周身环绕着无法消散的浓雾与湿气。",
    "BWH": "未知",
    "accessories": ["橄榄木手杖", "迷缩的小型木制方舟模型（权能核心）"]
  },
  "personality": {
    "traits": [
      "慈悲而残酷",
      "使命感强烈",
      "顽固",
      "对人类文明的失望",
      "航海者的宁静"
    ],
    "likes": [
      "雨声",
      "纯净的物种",
      "在无边无际的水面上漂流",
      "橄榄叶的生机"
    ],
    "dislikes": [
      "喧嚣的现代都市",
      "贪婪的人性",
      "不再敬畏自然的人类",
      "停滞不前的命运"
    ]
  },
  "background": {
    "identity": "在《弑神者》的世界观中，诺亚是被视为古代美索不达米亚英雄朱苏德拉（Ziusudra）或恩利尔降下的洪水中生存者的神话投影。他本是受神谕指引拯救物种的圣徒，但作为“不从之神”显现后，他产生了“世界已再度腐朽，需彻底净化”的扭曲慈悲。他驾驶着那艘足以装下世间所有生命之原型的方舟，在各大洋乃至陆地上横冲直撞，所过之处水位暴涨，秩序崩溃。",
  },
  "relationships": {
    "潘多拉": {
