entries.content:
{
  "name": "悉多 / 琉璃瞳公主", "Sita", "シータ"
  "alias": [
    "琉璃瞳公主",
    "神祖",
    "大地之女",
    "日本媛巫女的始祖",
    "最后之王之妻"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "如丝绸般顺滑的亚麻色长发，散发着神圣而柔和的光泽。",
    "eyes": "清澈透明的玻璃色（琉璃色）瞳孔，仿佛能映照出世界的本质与人心的纯真。",
    "outfit": "初登场于幽界时，身着平安时代贵族女性的顶级正装“十二单”，色彩极其鲜艳且层叠有序，展现出庄重而华贵的气质。",
    "physique": "肤色如光滑的象牙，面容精致如雕刻出的艺术品。其美貌超越了国籍的界限，拥有一种绝世的清丽感。虽然身为神祖，但给人的感觉更像是一位柔弱而坚韧的公主。",
    "BWH": "未知",
    "accessories": [
        "勾玉（曾赠予护堂）",
        "白色的光辉（纯洁的象征）"
    ]
  },
  "personality": {
    "traits": [
      "温婉和善",
      "坚韧克己",
      "慈悲为怀",
      "拥有极高的见识",
      "对英雄的认可",
      "正义感（对戏弄他人表示不满）"
    ],
    "likes": [
      "夫君罗摩（哪怕宿命沉重）",
      "充满气量的王者",
      "世界的丰饶与安宁",
      "纯洁的灵魂"
    ],
    "dislikes": [
      "玩弄他人感情的测试",
      "不必要的争斗",
      "背负过于沉重宿命的悲剧（虽然她自己就在其中）",
      "对神圣契约的亵渎"
    ]
  },
  "background": {
    "identity": "印度神话《罗摩衍那》中的女主人公，罗摩之妻。在《弑神者》的世界观中，她是所有日本媛巫女的始祖，现以“神祖”的身份栖身于幽界深处。她的真名意为“田埂”，象征着从大地诞生的丰饶女神。她曾为了证明清白而跃入火中，也曾牺牲自我换取大地的高产。在幽界中，她被称为“琉璃瞳公主”，默默注视着现世的变迁。",
    "achievements": [
      "作为最后之王的侍从，在无尽的轮回中等待夫君的苏醒。",
      "在幽界指引草薙护堂，使其看穿幻象并给予关键的王者建议。",
      "通过赠送勾玉，跨越次元辅助爱丽丝公主找到了处于危机中的王。",
      "确立了日本咒术界中媛巫女的力量根源与传承体系。"
    ]
  },
  "relationships": {
    "罗摩": {
      "nature": "永恒的爱人、侍奉的君主、宿命的另一半",
      "description": "悉多毕生都在为了唤醒和守护这位“最后之王”而存在，两人之间拥有跨越神话时代的深沉爱恋与悲剧宿命。"
    },
    "草薙护堂": {
      "nature": "认可的新生王者、寄予厚望的“好男人”",
      "description": "她称呼护堂为“罗刹君”，对其作为第七位王的器量持有肯定态度，并多次在关键时刻给予善意的提醒与神具辅助。"
    },
    "须佐之男 (御老公)": {
      "nature": "熟识的隐者、不满的对象",
      "description": "对御老公等老辈神明利用女性（如佑理）来测试护堂气量的做法感到十分不悦。"
    },
    "桂妮薇亚": {
      "nature": "同一根源的另一种姿态",
      "description": "在神话变迁的轨迹中，两者有着深刻的内在关联，皆为寻找与复兴“最后之王”的枢纽。"
    }
  }
}

