entries.content:
{
  "name": "命运之神", "Archetype of Destiny", "運命の神",
  "alias": [
    "太初之编织者",
    "不从之命运",
    "万神之母体",
    "剧本的持有者",
    "原型的幼女"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "如瀑布般垂落的披肩金发，闪烁着非尘世的光泽，仿佛由最纯粹的以太编织而成。",
    "eyes": "那是一双无法映照出任何情感的眼眸，其色彩在星空银与虚无黑之间不断流转，能够直视万物过去与未来的丝线。",
    "outfit": "全身赤裸，不着一丝。然而其神圣不可侵犯的威严化作了常人无法直视的灵光，如同一层薄纱覆盖在其如雪般白皙的肌肤上。由于其本质是原型，没有任何文明的修饰能定义她的存在。",
    "physique": "外表呈现为七、八岁左右的幼女，体型娇小玲珑，每一个轮廓都符合“最初之人”的黄金比例。尽管幼小，但当她立于大地之上，整个世界的重力感似乎都随之倾斜。",
    "BWH": "未知（神圣体态，不适用于凡人数值）",
    "accessories": ["命运之纺锤（无形之具象）", "永恒的时钟纹章"]
  },
  "personality": {
    "traits": [
      "冷酷无情",
      "极度理性",
      "神性的超然",
      "执着于剧本",
      "漠视生死",
      "秩序的化身"
    ],
    "likes": [
      "精确运行的历史轨迹",
      "闭合的命运圆环",
      "观测平行时空的收敛",
      "神话的完整性"
    ],
    "dislikes": [
      "变数",
      "跳脱时间轴的干扰者（如爱莎夫人的无序跳跃）",
      "弑神者这种破坏剧本稳定的“错误代码”",
      "不确定性"
    ]
  },
  "background": {
    "identity": "她是所有神话体系中“命运女神”的最原始原型（Archetype）。在希腊她是主宰定数的摩伊拉，在北欧她是守候泉水的诺恩，在印度她是万象母体帕尔瓦蒂。她并非某一个具体神话产生的神明，而是神话本身存在的基石。她以“不从”之姿降临并非为了破坏，而是发现原本的“历史剧本”因弑神者的频繁出没而产生偏离，故亲自降临担任历史的推动者，试图将偏差修正回其理想的轨道。",
    "purpose": "利用自身操纵时间与命运的权能，强行让特定的神明降临在特定地点，诱导弑神者按照她编排的“大决战剧本”行动，最终达成世界线的宏大收敛。"
  },
  "special_abilities": [
    {
      "name": "【命运之纺锤】 (Spindle of Fate)",
      "description": "能够操纵现实中的时间流速，并将万物的命运具象化为可以拨动的丝线。她能强行召集存在于神话狭缝中的不从之神降临，作为她剧本中的“棋子”。"
    },
    {
      "name": "【永恒的收敛】 (Eternal Convergence)",
      "description": "只要目标存在于当前的时间轴内，无论如何努力挣扎，最终都会被导向她所预设的结果。但在面对跨越平行时空而来的存在时，此权能会因为定位失效而无法发动。"
    }
  ],
  "relationships": {
    "草薙护堂": {
      "nature": "最大的变数、需要被修正或引导的“主角”",
      "description": "认为护堂的成长轨迹偏离了传统的英雄史诗，正在考虑是否通过引入新的“灾难”来修正他的性格。"
    },
    "潘多拉": {
      "nature": "竞争者、共犯",
      "description": "对潘多拉不断制造弑神者的行为感到不满，认为这增加了命运编织的难度。"
    },
    "爱莎夫人": {
      "nature": "天敌、无法干涉的错误",
      "description": "由于爱莎频繁跳跃于平行世界与过去未来，导致其命运丝线断裂，是命运之神唯一无法直接掌控的弑神者。"
    },
    "最后之王": {
      "nature": "终焉的执行者",
      "description": "将其视为剧本最后篇章的开启者，竭尽全力为其复苏扫清障碍。"
    }
  }
}

