entries.content:
{
  "name": "安洁拉", "Angela", "アンジェラ",
  "alias": [
    "阿榭拉 (Asherah)",
    "神祖",
    "苍蝇王总帅",
    "悖道之蛇",
    "利维坦 (Leviathan)"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "柔软且带有神圣感的亚麻色长发，通常自然垂落在纤弱的肩头。",
    "eyes": "深邃且透着魔性的瞳孔，在人类姿态下表现为一种超然世外的知性，在神格觉醒时会流露出蛇类的冰冷与威压。",
    "outfit": "通常以十岁左右的幼女形象示人，身着具有异域风情的精美长裙，或作为邪术师总帅时的神秘仪式装束。其姿态如同一具精巧而脆弱的人偶。",
    "physique": "身体素质极度特殊，外表虽是年约十岁的幼体，却蕴含着足以撼动大地的龙蛇之精气。在显现利维坦神格时，会变为身长超过五十米、覆盖银白色鳞片的巨大海兽利维坦。",
    "BWH": "未知（幼女体型）",
    "accessories": [
        "蛇之纹章",
        "作为利维坦显现时的银白色神圣鳞片"
    ]
  },
  "personality": {
    "traits": [
      "高傲神秘",
      "极度隐忍",
      "目的导向",
      "对宿命的觉悟",
      "知性与魔性并存"
    ],
    "likes": [
      "神话的复兴",
      "积攒力量的瞬间",
      "幽界的安宁"
    ],
    "dislikes": [
      "被当成牺牲品",
      "宿敌约翰·普鲁托·史密斯（冥王）的干扰",
      "神话被歪曲为恶兽的耻辱"
    ]
  },
  "background": {
    "identity": "身为神祖之一，安洁拉的真名实为‘阿榭拉’。由于在神话演变中，美索不达米亚的丰饶女神阿榭拉被贬为恶魔之属，其力量异化为海中巨兽‘利维坦’。她是北美最庞大的邪术师集团《苍蝇王》的灵魂人物，终其一生都在为了摆脱神祖的宿命、寻回失去的荣光而奔走。曾在威尼斯海域显现利维坦神体，引发了足以威胁城市的巨大海啸。",
    "achievements": [
      "统治邪术师结社《苍蝇王》，在北美建立了与正规结社抗衡的里世界势力。",
      "在漫长的岁月中，多次从宿敌‘冥王’的手中逃脱并重新集结力量。",
      "成功觉醒悖道之蛇神利维坦的神格，达到了足以抗衡弑神者的战斗力级别。",
      "参与了齐天大圣的解封仪式，成为关键的‘蛇’属性神格贡献者。"
    ]
  },
  "relationships": {
    "约翰·普鲁托·史密斯 (安妮·查尔顿)": {
      "nature": "一生之敌、互相牵制的魔王与魔女",
      "description": "两人在美国本土展开了跨越数年的明争暗斗，既是力量的对手，也是宿命中的双生影。"
    },
    "桂妮薇亚": {
      "nature": "同族、临时的盟友、救援者",
      "description": "同为寻找最后之王的神祖，在安洁拉战败命悬一线时，桂妮薇亚曾出手将其救走。"
    },
    "罗翠莲 (罗濠教主)": {
      "nature": "利用者与被利用者的关系",
      "description": "被教主以绝对的武力压制，作为解开齐天大圣封印的祭品工具人使用。"
    },
    "齐天大圣 (孙悟空)": {
      "nature": "掠夺者、吞噬其神力之神",
      "description": "在重伤状态下被齐天大圣活捉并转化为大灌丛般的形态吞噬，成为了大圣恢复元气的养分。"
    }
  },
  "special_powers": {
    "言灵·利维坦觉醒": "通过恢复神性的秘咒言灵，舍弃少女之躯，化为银鳞利维坦。此时具备操纵水流、制造大洪水以及吞噬大地精气的终极权能。",
    "神祖之血": "虽然失去了大部分神性，但作为神祖拥有顶尖的灵视力以及通过献祭仪式引导神明降临的禁忌知识。"
  }
}

