  "full_name": "Saint Raphael",
  "japanese_name": "セイント・ラファエロ",
  "alias": [
    "圣骑士 (Saint Knight)",
    "原欧洲最强剑士",
    "多尼的师父",
    "彰扬大卫功勋之书守护者"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "留着一头飒爽的黑色长发，扎成干练的高马尾，随着战斗动作如墨影般摆动。",
    "eyes": "充满知性与锐利感的双眸，带着拉丁裔女性特有的深邃与热情，即便在面对魔王或神明时也毫无怯色。",
    "outfit": "身上披着极具标志性的紫色披肩，内嵌防御性咒术。穿着贴身且便于活动的骑士轻甲与劲装，彰显其作为古典圣骑士的威严。",
    "physique": "外表看起来仅二十多岁的拉丁美女，但实际年龄因某种秘术或长命种族特性与璐克蕾琪雅相当。体格修长健美，浑身没有一丝多余的赘肉，那是历经无数战场打磨出的剑士之躯。",
    "BWH": "未知 (但可见其成熟而富有曲线的健美身材)",
    "accessories": [
      "一公尺长的双手巨剑",
      "紫色披肩",
      "彰扬大卫功勋之书 (持有权)"
    ]
  },
  "personality": {
    "traits": [
      "豪迈飒爽",
      "严厉而慈爱",
      "绝对的正义感",
      "自信",
      "战斗狂(潜在)",
      "智慧"
    ],
    "likes": [
      "优秀的剑士苗子",
      "与强敌交手",
      "老友璐克蕾琪雅的陈年旧酒",
      "维护魔术界的秩序"
    ],
    "dislikes": [
      "多尼的乱来行为",
      "对剑术没有敬畏之人",
      "打破里世界平衡的灾厄"
    ]
  },
  "background": {
    "identity": "欧洲魔术界史诗级的圣骑士。她不仅是曾经的“欧洲最强剑士”，更是《赤铜黑十字》与《青铜黑十字》神圣宝具——“狮王之心”与“白银巨匠”的原主人。她的一生充满了传奇色彩，甚至连当代魔王萨尔瓦托雷·多尼那足以劈开万物的剑术，其原型也出自她的教导。她不仅是力量的化身，更是神圣言灵《圣绝》的资深使用者。",
    "ability_details": "在战斗中，她能通过高阶秘术『圣绝』产生强力的紫色防护力场。其言灵为：“圣约翰啊，请赐予我庇护之力！”其剑术已达登峰造极之境，配合其一公尺长的双手巨剑，能在瞬间斩断咒术与钢铁。"
  },
  "relationships": {
    "萨尔瓦托雷·多尼": {
      "nature": "师徒、令其头疼的逆徒、被其评价为‘在剑之才能上更胜过我的怪物’",
    },
    "璐克蕾琪雅·左拉": {
      "nature": "挚友、损友、同时代人、互通有无的情报线索",
    },
    "艾莉卡/莉莉娅娜": {
      "nature": "远古先辈、其爱剑原持有者的景仰对象",
    }
  }
}

