entries.content:
{
  "name": "圣宾杜利乔", "Pinturicchio", "ピントゥリッキオ",
  "alias": [
    "圣平托瑞丘",
    "东尼的师父",
    "老贵妇人的新统帅",
    "圣拉菲尔的嫡传弟子"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "深褐色的短发，修剪得极度整齐，透着中年绅士特有的严谨与优雅感。",
    "eyes": "沉稳的灰色眼眸，总是带着一种透彻人心的智慧，哪怕在面对最狂暴的咒力冲击时也能保持古井无波。",
    "outfit": "经常穿着剪裁考究的西式三件套正装，外面披一件象征身份的长袍。在战斗或指挥结社时，会换上带有古代咒纹保护的礼装骑士铠甲，其上绣有圣拉菲尔分支的十字纹章。",
    "physique": "身高约182cm，体型修长而挺拔，虽然步入中年，但举手投足间展现出的肌肉控制力与灵活性依然处于巅峰状态。由于长期的磨炼，身上透着一种如利刃归鞘般的凝练气息。",
    "BWH": "未知",
    "accessories": ["师承圣拉菲尔的神圣护身符", "象征统帅地位的指挥剑"]
  },
  "personality": {
    "traits": [
      "稳重严谨",
      "名士风范",
      "责任感强",
      "深思熟虑",
      "教导者特质",
      "不苟言笑"
    ],
    "likes": [
      "完美的阵法布置",
      "品鉴古董",
      "看着弟子成长（虽然过程很头疼）",
      "维护魔术界的正统秩序"
    ],
    "dislikes": [
      "毫无计划的蛮干",
      "由于弟子乱来导致的巨额账单",
      "不守礼节的人",
      "失控的神话现象"
    ]
  },
  "background": {
    "identity": "欧洲魔术界极具声望的“大骑士”，是传奇魔术师圣拉菲尔的正式弟子。他不仅是第六位弑神者萨尔瓦托雷·东尼的授业恩师，更是南欧魔术结社联合中极具影响力的实力派人物。作为“老贵妇人”组织的新任统帅，他在里世界的地位极高，是极少数能通过纯粹的骑士技艺与战术谋略与弑神者产生的波纹进行周旋的人类强者。在同辈之中，唯有罗马的佛朗基斯科能与其并肩。",
    "achievements": [
      "教导出了被誉为“剑之王”的弑神者萨尔瓦托雷·东尼。",
      "在欧洲多次动乱中以卓越的指挥艺术化解危机。",
      "继任老贵妇人统帅，整合了托斯卡纳及周边区域的魔术势力。"
    ]
  },
  "relationships": {
    "萨尔瓦托雷·东尼": {
      "nature": "弟子、头疼的来源、现任的“王”",
      "description": "虽然他是东尼的师父，但面对这位弑神后变得更加乱来的弟子，他也常常感到深深的无奈。"
    },
    "圣拉菲尔": {
      "nature": "导师、引路人",
      "description": "他严格遵循着圣拉菲尔的教诲，将其魔术与骑士的精神传承了下去。"
    },
    "佛朗基斯科": {
      "nature": "宿敌、竞争对手、同阶层的好友",
      "description": "两人代表了当代意大利最顶尖的骑士实力，维持着一种微妙的竞争与平衡。"
    }
  }
}

