entries.content:
{
  "name": "大卫·皮安奇", "David Bianchi", "デイヴィッド・ビアンキ",
  "alias": [
    "卡利亚里的地相术师",
    "萨丁岛的一流术师",
    "大卫"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "剪裁得体的淡褐色短发，打理得丝毫不乱，显得精干而富有教养。",
    "eyes": "如同地中海深处般沉稳的蓝色眼眸，总是带着一种透彻的、审视大地律动的冷静感。",
    "outfit": "即便身处炎热的萨丁岛，也始终穿着一套剪裁精良、面料考究的深灰色或黑色西装。皮鞋锃亮，衬衫领口挺括，与其说是魔术师，更像是一位在市中心高级办公楼工作的精英律师或金融家。",
    "physique": "身高约180cm，身姿端庄整洁。由于长期从事地相术这种需要在大地奔走的工作，西装下的躯体其实相当结实且充满柔韧性，是一位二十五、六岁左右的美男子。",
    "BWH": "未知",
    "accessories": ["银质的地相观测仪", "怀表"]
  },
  "personality": {
    "traits": [
      "优雅端庄",
      "严谨务实",
      "高傲但不狂妄",
      "职业操守强",
      "注重效率",
      "追求美学平衡"
    ],
    "likes": [
      "完美的地脉流动",
      "合身的定制西装",
      "英国浪漫主义诗歌（如威廉·布莱克）",
      "高效率的合作者",
      "萨丁岛的传统美食"
    ],
    "dislikes": [
      "弄脏西装的污垢",
      "紊乱且无法调和的地脉",
      "鲁莽而没有计划的莽夫",
      "不守约定的雇主"
    ]
  },
  "background": {
    "identity": "活跃于萨丁岛首府卡利亚里的一流魔术师。虽然并非属于‘七姐妹’这种大型魔术结社的嫡系，但凭借其卓越的【地相术】（一种通过读取、干涉地脉来操作空间的魔术）在里世界享有极高盛名。他常年担任当地咒术界的顾问，负责监视和调整地脉中的咒力流动，是那种即便在‘王’（弑神者）降临的动乱中也能凭借专业知识保命并提供关键情报的精英人物。",
    "abilities": [
      "一流地相术：能够感知大地的呼吸，通过操纵局部空间的重力与连接来达到瞬移或囚禁敌人的目的。",
      "诗学言灵：擅长借用威廉·布莱克等诗人的诗句作为媒介，将深奥的魔术逻辑转化为具有即时杀伤力或创造力的咒术。其攻击手段兼具杀戮（死雾）、位移（空间连接）与召唤（食人虎）。"
    ]
  },
  "relationships": {
    "不从之神": {
      "nature": "深深敬畏且极力避开的对象。虽然是大名鼎鼎的一流术师，但有着清晰的自觉——绝不与神正面交锋。",
    },
    "弑神者": {
      "nature": "尊称为“陛下”，将其视为行走的天灾与雇主，维持着极高礼仪的从属与服务关系。",
    },
    "艾莉卡·布兰德里": {
      "nature": "同属地中海魔术圈的佼佼者。对其才能表示赞赏，但在追求‘王’的方式上持有不同的职业见解。"
    }
  }
}

