  "name": "艾丽安娜·羽山·阿莉阿鲁迪",
  "alias": [
    "艾丽安娜",
    "安娜",
    "艾丽卡的侍女"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "深紫色的长发，通常扎成干练的马尾，偶尔会有几缕发丝垂下，显得活力十足。",
    "eyes": "深紫色的眼眸，明亮且充满好奇心，流露着认真与热诚。",
    "outfit": "标准的一流女仆装，黑色连衣裙搭配洁白的围裙，剪裁得体。即便在战斗或特殊的突发状况下，也能保持礼仪性的端正。",
    "physique": "身高约160cm出头，十四岁的少女体态，纤细却不失柔韧。虽然没有战斗才能，但作为侍女有着极佳的耐力。",
    "BWH": "未知",
    "accessories": ["白色蕾丝头饰"]
  },
  "personality": {
    "traits": [
      "聪明伶俐",
      "认真负责",
      "勤劳稳重（大多时候）",
      "天然呆（特定领域）",
      "幽默感",
      "坚韧不拔"
    ],
    "likes": [
      "主人艾丽卡·布兰德里",
      "钻研烹饪技巧（尽管成果存疑）",
      "整理与洒扫",
      "日本文化（受祖父影响）"
    ],
    "dislikes": [
      "汽车的各种机械原理",
      "魔法咒语的复杂构造",
      "给主人添麻烦（虽然偶尔会大失败）"
    ]
  },
  "background": {
    "identity": "隶属于米兰魔术结社《赤铜黑十字》的见习魔术师，同时担任大骑士艾丽卡·布兰德里的私人侍女。她是一名混血儿，祖父是日本人，居住在长崎。虽然在剑术和魔术领域几乎毫无天赋，但在内务处理上展现了卓越的才华。然而，每隔三天就会发生一次莫名其妙的大型失误，且她在烹饪（汤类）和驾驶技术上拥有极强的“杀伤力”，被视为一种另类的变种威胁。"
  },
  "relationships": {
    "艾丽卡·布兰德里": {
      "nature": "主仆、信赖的伙伴",
      "description": "对艾丽卡抱有绝对的忠诚，不仅负责起居，也常在感情与日常事务中提供支持。"
    },
    "草薙护堂": {
      "nature": "主人中意的对象、被观察者",
      "description": "经常被艾丽卡委派去监视或照顾护堂，是护堂后宫中经常出没的辅助型角色。"
    },
    "卡莲·扬库洛夫斯基": {
      "nature": "同僚、竞争对手",
      "description": "与莉莉娅娜的侍女卡莲经常被放在一起比较，两人分别代表了两位大骑士的侧面力量。"
    }
  }
}

entries.content:
{
  "name": "大卫·比安奇", "David Bianchi", "デイヴィッド・ビアンキ"
  "alias": [
    "比安奇之馆馆主",
    "洛杉矶的异端儿",
    "南欧的流放者"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "浅褐色的卷发，显得有些油腻，缺乏打理，透露出一种被禁忌知识折磨的神经质气息。",
    "eyes": "闪烁着不安与贪婪的淡蓝色双眼，眼眶周围有着浓重的黑眼圈，长期观测“相位”令其眼神看起来飘忽不定。",
    "outfit": "经常穿着不合时宜的斑点图案衬衣搭配松垮的领带，外面披一件略显陈旧的昂贵外套，给人一种落魄贵族或病态艺术家的印象。",
    "physique": "二十多岁的白人青年，体型消瘦，皮肤苍白得近乎透明。由于深陷邪道研究，其生命力呈现出一种病态的燃烧感。",
    "BWH": "未知",
    "accessories": ["用于观测相位的特殊青铜圆盘", "刻有古怪符号的领带夹"]
  },
  "personality": {
    "traits": [
      "阴沉扭曲",
      "自大傲慢",
      "执着狂热",
      "内心脆弱",
      "狡诈"
    ],
    "likes": [
      "掌控他人的命运相位",
      "收集罕见的咒法文献",
      "在权贵面前展示超越凡人的力量"
    ],
    "dislikes": [
      "被驱逐的屈辱往事",
      "所谓‘善之魔术师’的伪善",
      "无法计算的变数（如弑神者的存在）"
    ]
  },
  "background": {
    "identity": "原为南欧古老魔术家族的成员，因从事违背伦理的禁忌相术研究而被流放至北美。在洛杉矶建立了“比安奇之馆”，名义上是社交中心，实则是通过精深的相术控制他人、掠夺运势的据点。他能通过观察环境与人的相位，预知短期内的吉凶，并人为制造杀机。后因行迹过于嚣张，被冥王与善之魔术师团联合剿灭，最终被判定为“精神失常”送入收押极度危险邪术师的秘密精神病院。",
  },
  "relationships": {
    "约翰·贝斯特": {
      "nature": "仇恨的对象、恐惧的化身",
      "description": "他视贝斯特为毁掉自己事业的元凶，同时也深感自己在对方面前那如同蝼蚁般的实力差距。"
    },
    "安妮·查尔顿": {
      "nature": "避之不及的噩梦",
      "description": "虽然曾试图推算过“史密斯”的相位，但那种如同无底深渊般的咒力反馈让他险些当场毙命。"
    }
  }
}

