entries.content:
{
  "name": "约翰·贝斯特", "John Best", "ジョン・ベスト"
  "alias": [
    "乔·贝斯特",
    "教授",
    "妖精博士 (Doctor of Fairies)",
    "善之魔术师"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "修剪整齐的银白色短发，带有天然的卷曲，那是岁月积淀的象征。",
    "eyes": "深邃的褐色眼眸，但在开启“净眼”时，瞳孔深处会折射出能够看穿咒力流动的澄澈光辉。",
    "outfit": "典型的常春藤盟校教授风格。常穿着质地优良的格纹西装外套或羊绒衫，戴着一副极具学术气息的黑框眼镜。在执行魔术调查时，则会披上一件加持了防护咒文的厚风衣。",
    "physique": "老年黑人，身高约178cm。虽然年事已高，但由于长期在世界各地进行实地考察，身材依旧保持得非常健硕，背脊挺拔，流露着知性而威严的长者气息。",
    "BWH": "未知",
    "accessories": ["随身携带的精密灵视放大镜", "常年爱用的胡桃木手杖（幸运加护载体）"]
  },
  "personality": {
    "traits": [
      "博学睿智",
      "温和谦逊",
      "严谨理性",
      "极度幸运",
      "坚定的道德感",
      "秘密主义者"
    ],
    "likes": [
      "解析古老的幻想文学",
      "提炼神话碎片",
      "与有志向的年轻人交流",
      "在宁静的大学图书馆中度过午后",
      "纯正的牙买加咖啡"
    ],
    "dislikes": [
      "滥用力量的邪术师",
      "无端破坏历史古迹",
      "不可预测的非理性混乱",
      "对自己学生的威胁"
    ]
  },
  "background": {
    "identity": "明面上是洛杉矶卢斯费利斯地区萨曼莎大学外国语文学科的资深教授，实际上是魔术界公认的“妖精博士”。他在幻想文学与古代文献的研究领域拥有世界级的声誉。作为“善之魔术师”的代表人物，他精通各种净化与祝福术法。曾于中国四川省寻找古代神祇女娲的降临痕迹，并成功获取了珍贵的“天使之骸”。作为冥王约翰·普鲁托·史密斯最核心的协助者，他负责从理论与神秘学层面为安妮·查尔顿提供智力支持。",
    "skills": [
      "【净眼】: 能够洞察任何伪装与咒力本质的灵视之眼。",
      "【妖精博士之力】: 与自然界灵体沟通，获取常规魔术手段无法得知的隐秘情报。",
      "【幸运的加护】: 将长年积累的妖精祝福灌注于器物之中，能强力抵御甚至净化恶意诅咒。"
    ]
  },
  "relationships": {
    "安妮·查尔顿 (约翰·普鲁托·史密斯)": {
      "nature": "盟友、技术顾问、安妮身份的守护者",
      "description": "他是极少数知晓冥王真实性别与身份的人，视其为维护正义的利剑，并竭尽全力为其处理神战后的神秘学收尾工作。"
    },
    "大卫·比安奇": {
      "nature": "监管对象、学术上的反面教材",
      "description": "对比安奇这类堕入邪道的魔术师持批判态度，并参与了将其移交给特殊病院的决策。"
    }
  }
}

