{
  "name": "克露提特 (克洛蒂德)", "Clothilde", "クロティルド"
  "alias": [
    "圣骑士",
    "乌尔丁第四妻",
    "卢恩文字的操纵者",
    "北方蛮族的明珠"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "如融化的流金般耀眼的长发，即使在硝烟弥漫的战场上也依然保持着令人心醉的神圣光泽。",
    "eyes": "如同北方深海般冷冽而高贵的碧蓝色眼眸，流露着属于武人的坚毅与属于皇室的高雅。",
    "outfit": "通常穿着一件银白色的全覆式轻量化板甲，搭配装饰有纯白羽饰的头盔。这种刚毅的圣骑士装扮下，依然掩盖不住其与生俱来的贵族格调。在凯旋式等社交场合，则会穿着带有民族特色的宫廷长袍。",
    "physique": "身高约175cm左右。高挑且匀称的身材展现出极佳的格斗天赋，长期穿着铠甲并进行圣骑士训练，使其体态充满了柔韧的爆发力。即便是在蛮族横行的时代，她也被视为女性英豪的典范。",
    "BWH": "未知",
    "accessories": ["黛莉拉的剃刀 (Delilah's Razor)", "刻有防御卢恩的护臂"],
    "vibe": "散发着神圣不可侵犯的‘战姬’气息。由于其作为乌尔丁（弑神者）的后宫成员，她的尊严背后有着来自魔王的绝对威压。"
  },
  "personality": {
    "traits": [
      "刚毅勇猛",
      "高雅从容",
      "绝对忠诚",
      "理智冷静",
      "自尊心极强",
      "护短（对后宫其他成员）"
    ],
    "likes": [
      "精进圣骑士战技",
      "在北欧森林中漫步",
      "乌尔丁的赞赏",
      "卢恩魔术的真理",
      "看着丈夫豪饮的样子"
    ],
    "dislikes": [
      "虚弱的阴谋家",
      "对乌尔丁不敬的宵小",
      "弄脏自己的铠甲",
      "被轻视为花瓶"
    ]
