      "勇武的战士"
    ],
    "dislikes": [
      "违背誓言的背叛者",
      "因神明乱行而造成的历史偏离",
      "混乱无序的末世"
    ]
  },
  "background": {
    "identity": "波斯神话中的核心主神，身兼契约、光芒与战争等多重职能。在《弑神者》的宇宙结构中，他曾作为前代“最后之王”的使命背负者，凭借救世神刀几乎将世界上的弑神者屠戮殆尽，导致了长达四百年的“魔王真空期”。虽然神体已在四百年前彻底崩毁，但凭借‘祖尔宛’的时间权能，他处于一种“停滞的终结”状态，等待着开启新的时代轮回。",
    "achievements": [
      "横跨多元世界尽头，跨次元召唤出军神韦勒斯拉纳。",
      "持有救世神刀，于四百年前清空了地上所有的弑神者。",
      "在超越时间的尽头守护着‘最后之王’的命运种子。",
      "以其死亡前的瞬间作为基点，锚定了未来可能出现的命运节点。"
    ]
  },
  "special_abilities": [
    {
      "name": "【契约之主的裁决】",
      "description": "凡是在其面前背弃誓言、违背律法之人，其灵魂与权能都会受到密特拉的压制。这是一种强制性的降格，能将神明或弑神者的位阶拉回到凡人的水平。"
    },
    {
      "name": "【极光之战士】",
      "description": "召唤出象征太阳神性与战神概念的实体，每一击都附带‘光’与‘热’的最终审判。"
    },
    {
      "name": "【祖尔宛的虚幻之视】",
      "description": "在时间秘神的加护下，即使身处濒死与破碎状态，亦能幻视未来的所有可能性，并挑选最适宜的未来进行‘最后之王’命运的托付。"
    }
  ],
  "relationships": {
    "韦勒斯拉纳": {
      "nature": "君臣、同源的神话脉络",
      "description": "他是密特拉意志的执行者，曾响应密特拉的跨界召唤而来，两者共同构筑了波斯神话的战争顶点。"
    },
    "祖尔宛": {
      "nature": "加护者、法则来源",
      "description": "为其提供时间停滞的核心神力，使得密特拉能在身体毁灭后依然作为“观察者”存在。"
    },
    "第七位王": {
      "nature": "候选者、传承之人",
      "description": "密特拉在时间的缝隙中注视着新生者，考量其是否有资格承接拯救与终焉的宿命。"
    }
  }
}

entries.content:
{
  "name": "祖尔宛", "Zurvan", "ズルワーン"
  "alias": [
    "永劫与无限之秘神",
    "光明与黑暗的创造主",
    "时之超越者",
    "时间与命运的终极概念"
  ],
  "appearance": {
    "gender": "无 (具象化为狮头面具姿态)",
    "hair": "无 (石制躯体)",
    "eyes": "在石质面具后的虚无之眼，虽然没有瞳孔，但其视线跨越了过去、现在与未来的所有节点。",
    "outfit": "并非实体衣物。呈现为一副以狮子为造型的古老石面具，两端各缠绕着一条代表循环与永恒的石蛇。",
    "physique": "作为非人格化的概念神显现，其存在感稀薄且无定形，常以一种类似石质浮雕或幽影的形式出现在宇宙的核心或尽头。",
    "accessories": ["双首之蛇", "狮王之面"]
  },
  "personality": {
    "traits": [
      "绝对中立",
      "无机质",
      "虚无感",
      "恒久性",
      "超脱善恶"
    ],
    "likes": [
      "时间的自然流动",
      "因果的闭环",
      "平衡的状态"
    ],
    "dislikes": [
      "对时间线无意义的恶意破坏",
      "试图跳出永劫轮回的卑微挣扎 (虽然这本身也在其意料内)"
    ]
  },
  "background": {
    "identity": "波斯萨珊王朝时期被尊奉的至高时间神。他是奥尔穆兹德与阿里曼的父亲，象征着在二元对立产生之前的原始统一状态。在《弑神者》世界观中，他并非活跃的‘不从之神’，而是近乎于世界基石的‘秘神’，掌管着万物的生灭与宿命的刻度。",
    "voice": "因其起源于抽象的时间流动，被赋予人格化后的声音冰冷、干燥且不带一丝情感，如同齿轮咬合时的共鸣。"
  },
  "special_abilities": [
    {
      "name": "【永劫的时间轴】",
      "description": "能够干涉一个区域、甚至是一个神明的时间刻度。让万物在永恒与瞬间之间切换。他让密特拉的时间停滞在死亡前的一瞬，正是此权的运用。"
    },
    {
      "name": "【命运的螺旋线】",
      "description": "由于其创造了光明与黑暗，世间所有宿命都在他的注视之下。这种权能使得被加护者能够观察到必然发生的‘果’。"
    },
    {
      "name": "【阿尔法与欧米茄】",
      "description": "作为开始与结束的统一体，具有重置小规模世界历史走向的可能性（需付出极大的咒力代价）。"
    }
  ],
  "relationships": {
    "密特拉": {
      "nature": "侍奉者与守护对象",
      "description": "祖尔宛认可密特拉对秩序的追求，并以此作为停滞其时间的契约条件。"
    },
    "潘多拉": {
      "nature": "概念性的共鸣",
      "description": "同样身为干涉“诞生”与“契约”的母神/父神级别存在，两人在宇宙更高维度的法则上互有接触。"
    }
  }
}

