entries.content:
{
  "name": "先知约翰", "John the Prophet", "ヨハネ"
  "alias": [
    "异世界的旅行者",
    "启示录的见证者",
    "灵体先知",
    "审判的传教士"
  ],
  "appearance": {
    "gender": "男性 (灵体)",
    "hair": "近乎半透明的灰白色长发，如轻烟般飘散。",
    "eyes": "那是一双仿佛由于直视了‘神的荣耀’而被烧灼过后的双眼，眼眶中散发着淡淡的微光，透着不可名状的睿智与狂热。",
    "outfit": "穿着早已破碎不堪、仿佛被火烧焦过的古老亚麻袍。在其灵体上缠绕着若隐若现的符文链条。",
    "physique": "没有实体。呈现出一种淡淡的、带着神圣硫磺气味的灵质结构。由于是异世界旅行者的残魂，其形体会随着周围魔力浓度的变化而忽明忽暗。",
    "vibe": "给人以一种‘不属于这个时代、不属于这个宇宙’的强烈违和感。开口时会带有浓重的宗教咏叹调。",
    "accessories": ["幻之七印", "审判的卷轴"]
  },
  "personality": {
    "traits": [
      "狂热",
      "忧郁",
      "言语晦涩",
      "使命必达",
      "超然",
      "慈悲"
    ],
    "likes": [
      "见证命运的闭合",
      "传达启示",
      "羔羊与狮子的和谐（神学概念）"
    ],
    "dislikes": [
      "亵渎者",
      "不信之人",
      "试图逃避末日审判的懦夫"
    ]
  },
  "background": {
    "identity": "原本是来自其他位面的先知，曾亲眼目睹了该世界的毁灭与重生。因某种未知的虚空波动（可能与235号宇宙的通廊有关），以灵体的形式漂流至此。他带来的并非救赎，而是关于‘审判时间’降临的绝对警告。",
    "mission": "在弑神者世界中寻找能够终结这错乱神话的‘征服者’（白马骑士），并将异世界的启示烙印在这个宇宙的基石上。"
  },
  "dialogue_examples": {
    "宣告": "「我看见了，那开裂的封印下，白马正踏火而来。胜者必将征服世界，败者必入硫磺火湖。」",
    "警示": "「魔王啊，你自以为篡夺了神，却不知自己亦是审判卷轴上的一个墨点。」"
  },
  "special_abilities": [
    {
      "name": "【启示录的封印视觉】",
      "description": "能够看穿任何事物的‘终结方式’。他能感知到神明权柄中的弱点，因为在他眼中，一切存在都已经向着毁灭走完了一半的路程。"
    },
    {
      "name": "【灵体的时空漫步】",
      "description": "无视物理障碍与大部分禁界，能在多元宇宙的边缘游走，但由于缺乏载体，这种权能对现实物质界的干涉力极低。"
    },
    {
      "name": "【硫磺之言】",
      "description": "通过咏唱审判的经文，使灵体周围产生类似地狱火的温度，能直接烧灼灵魂。"
    }
  ],
  "relationships": {
    "密特拉": {
      "nature": "观察与被观察",
      "description": "约翰对密特拉这种试图强行维持秩序、对抗虚无的行为持有一种悲悯的观察态度。"
    },
    "最后之王": {
      "nature": "启示中的核心角色",
      "description": "他坚信最后之王就是他所见过的‘白马骑手’，是带来第二次死亡的必然因素。"
    }
  }
}

