    "accessories": ["神剑·天丛云剑", "伊邪那美的母爱之枷（脖颈处的隐形神力项圈）"]
  },
  "personality": {
    "traits": [
      "暴戾与理性的平衡",
      "极度的母性依赖（对伊邪那美）",
      "对胜负的绝对执着",
      "出云之王的领袖气质",
      "毁灭性的征服欲"
    ],
    "likes": [
      "铁与血的味道",
      "伊邪那美的嘉奖",
      "以弱胜强的战斗",
      "神剑鸣响的声音"
    ],
    "dislikes": [
      "被神话束缚的宿命",
      "软弱的降神术",
      "八岐大蛇的余味",
      "高天原的伪善"
    ]
  },
  "background": {
    "identity": "在966号宇宙中，须佐之男并非自行降临的不从之神，而是被身处黄泉的‘母神’伊邪那美，以八岐大蛇作为祭品强行唤醒并塑造的战斗兵器。他不仅继承了原本神话中‘钢’之英雄的力量，更因祭品的缘故，完美继承了八岐大蛇的物理特性。他是为了在现世重建‘铁砂之国·出云’并作为母神回归的先锋而存在的‘暴虐之王’。",
    "achievements": [
      "血祭降临：在黄泉比良坂，以八岐大蛇之血洗涤神躯，重获神位。",
      "夺取神钢：在神话的重演中，用蛮力斩断大蛇之尾，掠夺了象征日本最强武装力量的‘天丛云剑’。",
      "出云霸权：试图将整个日本转化为以铁砂与神剑堆砌的永恒堡垒。"
    ]
  },
  "relationships": {
    "伊邪那美": {
      "nature": "造物主、母神、支配者",
      "description": "对其抱有复杂且扭曲的爱，既想反抗她的操控，又渴望得到她的认同，是其精神上唯一的弱点。"
    },
    "草薙护堂 (若与之相遇)": {
      "nature": "宿命的竞争者、篡夺者",
      "description": "认为对方不配持有‘草薙’之名，发誓要将对方右手中的神剑残余收回。"
