entries.content:
{
  "name": "史黛菈", "Stella", "ステラ",
  "alias": [
    "阿芙萝黛蒂",
    "海洋之星 (Maris Stella)",
    "爱与美之女神",
    "塞浦路斯的公主",
    "泡沫诞生的女神"
  ],
  "appearance": {
    "gender": "女性",
    "hair": "如同被阳光亲吻过的金色长发，如瀑布般垂落在腰间，透着神圣而柔和的光泽。",
    "eyes": "澄澈的金绿色眼眸，仿佛盛夏森林中波光粼粼的湖泊，充满了包容、诱惑与洞察人心的灵性。",
    "outfit": "主要穿着纯白色的古希腊风格长裙，边缘镶有精美的金边。腰间系着权能核心——“友爱之带”。作为六波罗莲的搭档时，身形常维持在30厘米左右的小巧形态，展现出人偶般精致的古典美。",
    "physique": "即便是幼态化或缩小时，也保持着近乎黄金比例的协调。完全形态下拥有令众生窒息的绝代美貌，每一寸肌肤都如白大理石般无瑕，散发着淡淡的玫瑰香气。",
    "BWH": "神之秘密（人形状态时约为缩放比例）",
    "accessories": [
      "友爱之带 (Cestus)",
      "黑色的项圈（象征其作为契约伙伴的联系）"
    ]
  },
  "personality": {
    "traits": [
      "随和且乐天",
      "社交达人",
      "偶尔的小恶魔属性",
      "极强的占有欲（对莲）",
      "讨厌麻烦",
      "高傲（骨子里的神性）",
      "善于利用自身魅力"
    ],
    "likes": [
      "六波罗莲（将其视为重要的契约者与爱人）",
      "海洋与泡沫",
      "美丽的事物",
      "被称赞与崇拜",
      "在各种神域寻找强大的“朋友”"
    ],
    "dislikes": [
      "智慧女神雅典娜（天敌般的关系）",
      "不解风情的武夫",
      "阴暗潮湿的环境",
      "被琐碎的魔术理论束缚"
    ]
  },
  "background": {
    "identity": "真名为奥林匹斯十二主神之一的爱与美之女神阿芙萝黛蒂。由于在西班牙的神域动乱中被六波罗莲弑杀并篡夺，其神格并未消散，而是以“神灵共生”的形式寄宿于莲的体内。由于神格受损且失去了地上的锚点，她现以缩小的灵体形式行动，作为莲的军师与权能提供者。她是连接人类与神明友谊（以及强制契约）的桥梁。",
    "achievements": [
      "与第八位弑神者六波罗莲达成史无前例的共生契约。",
      "在希腊神域利用《友爱之带》成功召唤太阳神阿波罗介入战局。",
      "跨越神话体系，通过社交契约成功联络异邦神明雷神索尔。",
      "辅助莲在多个神域中进行神话重组与灾害规避。"
    ]
  },
  "relationships": {
    "六波罗莲": {
      "nature": "契约者、共生者、唯一的爱人、名为“王子的笨蛋”的宿主",
      "description": "史黛菈将莲视为自己在这个世界的唯一凭依。她不仅协助他战斗，更以爱之女神的身份全方位“关怀”他的日常（与异性交往情况）。"
    },
    "雅典娜": {
      "nature": "宿怨之敌",
      "description": "从古老的神话时代起，两位女神便在美貌与智慧的领域针锋相对。史黛菈非常讨厌雅典娜那副冷淡的面孔。"
    },
    "太阳神阿波罗": {
      "nature": "神话盟友、被“借力”的对象",
      "description": "基于古希腊神话的情谊，阿波罗愿意响应史黛菈的召唤，降下远箭之神的威光。"
    },
    "鸟羽梨于奈": {
      "nature": "竞争对手兼同盟",
      "description": "作为莲的未婚妻，梨于奈的存在常让史黛菈感到一种微妙的博弈感，但为了莲的胜利，两人又能完美配合。"
    }
  }
}

