  "background": {
    "identity": "降临于世的‘不从之阿波罗’。他不仅仅是光明的化身，更是神话中多面性的集合体。作为起源于北方极寒之地（许柏尔柏瑞亚）的英雄，他在地底黑暗中诞生，最终却升华成了照耀地表的烈阳。他既是赐予生命与健康的治愈之神，也是散播致命瘟疫的收割者。其本质是以‘理性’裁决世界的英雄，用神喻锁定敌人的命运，再以必中的光矢将其抹除。他降临现代世界，是为了寻找曾经失去的‘英雄之路’，并意图通过‘火之仪式’将尘世重新洗练。"
  },
  "relationships": {
    "阿尔忒弥斯": {
      "nature": "双胞胎姐姐、狩猎与月亮的同行者、神话的另一半面"
    },
    "沃班侯爵": {
      "nature": "宿敌、弑杀过‘另一个阿波罗’的猎人、极其厌恶的对象"
    },
    "萨尔瓦托雷·东尼": {
      "nature": "对其鲁莽与缺乏理性的蛮力感到不悦、视为麻烦的对手"
    },
    "潘多拉": {
      "nature": "解析其神性的观测者、宿命的引导者"
    }
  }
}

