entries.content:
"name": "波塞冬", "Poseidon", "ポセイドン"
  "alias": [
    "不从之波塞冬",
    "海与大地之神",
    "震地之王 (Earth-Shaker)",
    "毁船者",
    "马匹之神",
    "古老的暗色之王"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "深蓝色的卷曲长发，如同深夜的海底一般幽暗，发丝间夹杂着盐分结晶与古老的诅咒。",
    "eyes": "如同深渊般的碧蓝色，透着无边汪洋的冷酷与狂暴，直视其双眼仿佛会被卷入深海的漩涡。",
    "outfit": "上身赤裸，展示出极其庞大的神体；下身覆盖着如同海草般纠结、散发着幽光的古老裙带。腰间缠绕着以深海巨兽皮革制成的宽大腰带。",
    "physique": "身高两百公尺左右的巨人姿态。肤色呈现深邃的蓝黑色，如同承受了数万气压的深海。肌肉虬结如山脉，即便只是静止不动，周身散发的咒力波纹也能让海水瞬间沸腾。",
    "BWH": "未知 (神体规模无法计算)",
    "accessories": [
        "三叉戟 (Trident)",
        "海皇之冠"
    ],
  },
  "personality": {
    "traits": [
      "狂暴如潮",
      "反复无常",
      "原始的傲慢",
      "对大地的支配欲",
      "视凡人为草芥",
      "强烈的侵略性"
    ],
    "likes": [
      "海洋的肆虐",
      "震动大地的快感",
      "恐惧的祭祀",
      "毁灭人类的船只"
    ],
    "dislikes": [
      "被天空神压制",
      "弑神者的阻挠",
      "陆地文明的宁静",
      "虚弱的生命气息"
    ]
  },
  "background": {
    "identity": "降临于现世的希腊主神之一，其神格不仅限于海洋，更是远古的‘大地之神’。在神话中，他是宙斯的兄弟，但在不从之身态下，他表现出了对宙斯权威的挑战欲望。波塞冬降临后，其两百米高的巨躯足以引起全球性的海啸。他拥有操控洋流与板块运动的原始权能，是名副其实的移动天灾。",
  },
  "relationships": {
    "宙斯": {
      "nature": "兄弟、竞争对手、共同构筑天空与海洋统治的顶点",
    },
    "六波罗莲": {
      "nature": "强劲的宿敌、能够抗衡神圣威压的‘猿猴’",
