    "不从之瓦哈格恩",
    "火之战士",
    "屠龙者",
    "韦勒斯拉纳的亚美尼亚之名"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "灿烂如金的金色卷发，每一缕发丝都仿佛跳动的火星。",
