entries.content:
{
  "name": "理查德·一世", "Richard I", "リチャード1世"
  "alias": [
    "狮心王",
    "圆桌骑士团代理团长",
    "英格兰的毁灭之剑"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "如狮子鬃毛般狂野的金色中短发，充满野性的质感。",
    "eyes": "清澈而锐利的碧蓝色眼眸，像是在寻找猎物的狮王。",
    "outfit": "穿着厚重的白金色全身重铠，外罩一件绣有三金狮纹章的赤红色罩袍。即便是在‘圆桌之都’的日常中，他也从不离去背后的白色大氅。",
    "physique": "身高超过190cm的魁梧战士，肩膀宽阔，宛如一座移动的钢铁堡垒。其身躯蕴含着由于‘英雄化’而带来的怪力。",
    "BWH": "未知",
    "accessories": ["十字军十字架", "狮头铁护腕"]
  },
  "personality": {
    "traits": [
      "狂傲不羁",
      "武勇至上",
      "豪迈",
      "护短",
      "极致的骑士道"
    ],
    "likes": [
      "正面决斗",
      "狄奥多里克的‘反命运’理想",
      "烈酒与凯旋歌",
      "与剑之王萨尔瓦托雷切磋"
    ],
    "dislikes": [
      "阴谋诡计",
      "被神明愚弄的命运",
      "自命清高的智慧之神"
    ]
  },
  "background": {
    "identity": "历史上著名的英格兰国王，五年前因某种异变转生至‘英雄界许柏尔柏瑞亚’。虽然失去了凡世的王位，却由于弑神者狄奥多里克的咒力赐福与许柏尔柏瑞亚的规则修正，获得了近乎‘半神’的肉体与魔技。他宣誓效忠于狄奥多里克，并以自身的统率力将圆桌之都的骑士们打造成了一支无坚不摧的战团。其剑技之精湛，被东尼评价为‘能在纯武艺上与之比肩的凡人’。",
  },
  "relationships": {
    "狄奥多里克": {
      "nature": "君臣、信赖的战友",
      "description": "将狄奥多里克视为真正能改变神话结构的唯一王者，愿为其挥剑直至神域终焉。"
    },
    "萨尔瓦托雷·东尼": {
      "nature": "武艺上的至交好友、宿敌",
      "description": "两人曾多次在比武场较量，理查德极度欣赏东尼那种除了剑以外别无他物的纯粹感。"
    },
    "黑王子爱德华": {
      "nature": "长辈与后辈、战团同僚",
      "description": "虽然两人皆是名震史册的战将，但理查德更倾向于冲锋陷阵，经常由于爱德华的精密计算而感到头疼。"
    }
  },
  "special_abilities": [
    {
      "name": "魔剑 Excalibor",
      "description": "由于狄奥多里克弑杀亚瑟王后夺取的‘圆桌权能’，理查德获得了原本属于圣剑的一部分投影。他手中的巨剑能通过注入神圣咒力，像现代兵器般发射出横贯地平线的金色激光束，瞬间贯穿巨龙的鳞甲。"
    }
  ]
}

