{
  "name": "爱德华·普兰塔戈奈特", "Edward Plantagenet", "エドワード黒太子"
  "alias": [
    "黑王子",
    "阴影下的处刑人",
    "圆桌指挥官"
  ],
  "appearance": {
    "gender": "男性",
    "hair": "如霜似月的银色长发，通常被一条黑色缎带束在脑后，显得精致且冷酷。",
    "eyes": "灰蓝色的眼眸，常年保持着冷静的观察态势，宛如冰冷的寒潭。",
    "outfit": "穿着特制的黑色皮甲，外挂深色轻便金属护具。披着一件边缘被裁碎的墨色长披风。手持一把由黑木打造、刻满秘银咒文的长弓。",
    "physique": "看起来只有二十岁左右的银发青年，体态比起理查德显得纤细修长，但每一根线条都充斥着致命的平衡感与张力。",
    "BWH": "未知",
    "accessories": ["银质雄狮挂饰", "追踪用黑曜石戒指"]
  },
  "personality": {
    "traits": [
      "冷静理智",
      "效率至上",
      "毒舌",
      "忠诚",
      "精密周全"
    ],
    "likes": [
      "精确的战术伏击",
      "擦拭羽箭",
      "夜间的巡视",
      "安静的阅览室"
    ],
    "dislikes": [
      "鲁莽的冲锋",
      "理查德那震天响的笑声",
      "由于意外导致的战损"
    ]
  },
  "background": {
    "identity": "与理查德一同转生至许柏尔柏瑞亚的英国传奇统帅。他将理查德称为‘伯父’，虽然两人在历史时空上并无交集，但在狄奥多里克的领域内，他们建立起了一种基于家族荣誉与血缘感的羁绊。爱德华担任‘圆桌之都’的战略参谋，负责一切涉及精密打击与防御的任务。他将神话中的‘英雄弓箭’与现代弩机原理结合，成为了战场上死神的化身。",
  },
  "relationships": {
    "狄奥多里克": {
      "nature": "宣誓效忠的绝对王",
      "description": "认为狄奥多里克是这个崩溃世界中唯一的理智之源，通过他的秩序，爱德华能找到杀戮的真正价值。"
    },
    "狮心王·理查德": {
      "nature": "尊敬的伯父、鲁莽的重甲堡垒",
      "description": "虽然对理查德的武技充满敬意，但经常公开吐槽其缺乏智谋的作战计划。"
    }
  },
  "special_abilities": [
    {
      "name": "极暗箭雨 (Shadow Rain)",
      "description": "通过向天空射出一支母箭，瞬间在空中通过空气中的咒力制造出数以万计的黑影复制体。这阵规模浩大的‘箭之雨’足以覆盖整个城邦，且每一支箭矢都带有追踪灵魂的效果。"
    }
  ]
}

