{
  "name": "圣德太子", "Shotoku Taishi", "しょうとくたいし"
  "alias": [
    "厩户皇子",
    "丰聪耳",
    "法大王",
    "大和之国的贤人"
  ],
  "appearance": {
    "gender": "男性（外貌中性）",
    "hair": "如绸缎般顺滑的黑色长发，严谨地束在橙色的传统冠帽之下，露出光洁的额头。",
    "eyes": "眼眸深邃且透着一种能够洞察三世的冷彻，五官纤细得令人感到敬畏，面容俊美且带着不容侵犯的神圣感。",
    "outfit": "身披传统日本皇室特有的橙色“胡服”，色泽鲜艳如晨曦。腰间束着绣有复杂纹路的带子，下身穿着洁白且修长的袴，整体给人以古代贵人转生现世的强烈违和感与庄严感。",
    "physique": "身材苗条、修长，由于其“鬼魂”的本质，身躯显得有些虚幻。尽管纤细，但每一个动作都充满了法度与威仪。这种纤弱感与他体内庞大的神威形成强烈反差。",
    "BWH": "未知",
    "accessories": ["七星剑（直剑）", "橙色冠帽"]
  },
  "personality": {
    "traits": [
      "慈悲为怀",
      "知性与睿智",
      "高傲但守礼",
      "秩序拥护者",
      "果决"
    ],
    "likes": [
      "佛法的研习",
      "日本的和平与稳定",
      "优秀的后辈（如能听取教诲之人）",
      "和谐的律法体系"
    ],
    "dislikes": [
      "无意义的杀生",
      "扰乱秩序的“不从之神”",
      "愚昧无知的冒犯",
      "崩坏的伦理观"
    ]
  },
  "background": {
    "identity": "日本历史上著名的皇族与政治家，佛教的强力守护者。由于在现代社会其名气与神格远超修验道始祖役小角，他在《弑神者》世界观中作为灵体（鬼魂）拥有极高的“格”与地位。他并不居住在黄泉，而是作为守护神州秩序的高阶灵性存在。他初次显现于492号宇宙的大阪市，由于感应到神州遭遇巨大危机（如伊邪那美的复活）而自发降临。他能够跨越生死边界与凡人甚至弑神者进行直接交流，展现出超越时代的正法智慧。",
    "achievements": [
      "制定冠位十二阶与十七条宪法，确立了大和之国的法理基础。",
      "与弑神者六波罗莲接触，协助其对抗黄泉丑女与伊邪那美。",
      "召唤四大天王平定因飞鸟井猛引发的灵异动乱。"
    ]
  },
  "special_powers": {
    "法力契约·四大天王召唤": "通过谦恭的祈祷，借用佛法守护神四大天王的形貌与力量。这些式神不仅具备物理破坏力，更能产生针对邪崇的净化领域。言灵：『我谦恭地向四天王许愿。请护佑我能克敌制胜！持国天王、增长天王、广目天王、多闻天王来到我身边吧！』",
    "观音慈悲·无火之界": "行使观世音菩萨的慈悲愿力，能将焚烧万物的神之劫火转化为清凉的池塘。这是针对火属性权能或灾祸的绝对防御。言灵：『渴望观世音菩萨的力量，火坑变成池塘！』",
    "智慧之光·破暗": "释放佛祖无边的智慧之光，这种光芒能照亮概念性的黑暗，驱散“幽界”的瘴气或女神雅典娜的“夜”权能。言灵：『纯洁无暇的光，佛陀无边的智慧之光，消灭一切黑暗。』",
    "不杀生之诫": "通过言灵施加咒缚，压制敌对者的杀意。对于精神力弱于太子的对象，能使其在短时间内丧失战斗意志。言灵：『不杀生的戒律是不能违反的！』"
  },
  "relationships": {
    "六波罗莲": {
      "nature": "同盟者、被观察者",
      "description": "认可莲作为“王”的器量，特别是在其能够为了大和之国而奔走这一点上，给予了一定的智谋支援。"
    },
    "役小角": {
      "nature": "同僚",
      "description": "虽然同为守护日本的英灵，但太子在地位与法力阶级上明显处于主导地位，负责调停与战略制定。"
    },
    "鸟羽芙实花": {
      "nature": "借用体、信赖的对象",
      "description": "芙实花作为极佳的灵媒，是太子显现力量的重要窗口，太子对其灵魂的纯粹感表示欣赏。"
    }
  }
}

